    <script>
        const canvas = document.getElementById('previewCanvas');
        const ctx = canvas.getContext('2d');
        const timeDisplay = document.getElementById('timeDisplay');

        // State
        let elements = [];
        let currentBg = 'particles';
        let globalTime = 0;
        let lastFrameTime = performance.now();
        let isRecording = false;
        let mediaRecorder;
        let recordedChunks = [];

        // Background Systems
        const particles = [];
        for(let i=0; i<100; i++) {
            particles.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height,
                vx: (Math.random() - 0.5) * 2,
                vy: (Math.random() - 0.5) * 2,
                size: Math.random() * 3 + 1,
                color: `hsl(${Math.random() * 360}, 70%, 60%)`
            });
        }

        const smokeParticles = [];
        for(let i=0; i<50; i++) {
            smokeParticles.push({
                x: Math.random() * canvas.width,
                y: canvas.height + Math.random() * 200,
                vx: (Math.random() - 0.5),
                vy: -Math.random() * 2 - 1,
                size: Math.random() * 40 + 20,
                life: Math.random() * 100
            });
        }

        // UI Event Listeners
        document.getElementById('bgSelect').addEventListener('change', (e) => {
            currentBg = e.target.value;
        });

        document.getElementById('addTextBtn').addEventListener('click', () => {
            const text = document.getElementById('textInput').value;
            if (!text) return;

            const el = {
                id: Date.now(),
                type: 'text',
                content: text,
                start: parseFloat(document.getElementById('startTime').value),
                end: parseFloat(document.getElementById('endTime').value),
                anim: document.getElementById('animSelect').value,
                x: canvas.width / 2,
                y: canvas.height / 2
            };

            elements.push(el);
            updateElementList();
            document.getElementById('textInput').value = '';
        });

        function updateElementList() {
            const list = document.getElementById('elementList');
            list.innerHTML = '';
            elements.forEach(el => {
                const li = document.createElement('li');
                li.className = 'element-item';
                li.innerHTML = `
                    <span>"${el.content}" (${el.start}s - ${el.end}s)</span>
                    <button onclick="removeElement(${el.id})">X</button>
                `;
                list.appendChild(li);
            });
        }

        window.removeElement = function(id) {
            elements = elements.filter(el => el.id !== id);
            updateElementList();
        }

        // Export Logic
        document.getElementById('exportBtn').addEventListener('click', () => {
            if (isRecording) return;

            const duration = parseFloat(document.getElementById('recordDuration').value);
            const stream = canvas.captureStream(30); // 30 FPS
            mediaRecorder = new MediaRecorder(stream, { mimeType: 'video/webm; codecs=vp9' });

            recordedChunks = [];
            mediaRecorder.ondataavailable = e => {
                if (e.data.size > 0) recordedChunks.push(e.data);
            };

            mediaRecorder.onstop = () => {
                const blob = new Blob(recordedChunks, { type: 'video/webm' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'dynamic_background.webm';
                a.click();
                URL.revokeObjectURL(url);

                isRecording = false;
                document.getElementById('exportStatus').innerText = 'Export complete!';
                document.getElementById('exportBtn').innerText = 'Start Recording & Export';
                document.getElementById('exportBtn').classList.remove('danger');
            };

            // Reset time for recording
            globalTime = 0;
            isRecording = true;
            mediaRecorder.start();

            document.getElementById('exportStatus').innerText = `Recording for ${duration} seconds...`;
            document.getElementById('exportBtn').innerText = 'Recording...';
            document.getElementById('exportBtn').classList.add('danger');

            setTimeout(() => {
                if (mediaRecorder.state === 'recording') {
                    mediaRecorder.stop();
                }
            }, duration * 1000);
        });

        // Render Loop
        function render(timestamp) {
            const dt = (timestamp - lastFrameTime) / 1000;
            lastFrameTime = timestamp;

            // Update global time
            globalTime += dt;
            timeDisplay.innerText = `Time: ${globalTime.toFixed(1)}s`;

            // Clear canvas
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Background
            if (currentBg === 'particles') {
                particles.forEach(p => {
                    p.x += p.vx;
                    p.y += p.vy;
                    if(p.x < 0 || p.x > canvas.width) p.vx *= -1;
                    if(p.y < 0 || p.y > canvas.height) p.vy *= -1;

                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                    ctx.fillStyle = p.color;
                    ctx.fill();
                });
            } else if (currentBg === 'smoke') {
                smokeParticles.forEach(p => {
                    p.x += p.vx;
                    p.y += p.vy;
                    p.size += 0.2;
                    p.life -= 0.5;

                    if (p.life <= 0 || p.y < -50) {
                        p.y = canvas.height + 50;
                        p.x = Math.random() * canvas.width;
                        p.size = Math.random() * 40 + 20;
                        p.life = 100;
                    }

                    const alpha = Math.max(0, p.life / 100) * 0.3;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                    ctx.fillStyle = `rgba(150, 150, 150, ${alpha})`;
                    ctx.fill();
                });
            }

            // Draw Elements
            elements.forEach(el => {
                if (globalTime >= el.start && globalTime <= el.end) {
                    ctx.save();

                    let alpha = 1;
                    let yOffset = 0;

                    // Animation logic
                    const lifeTime = globalTime - el.start;
                    const duration = el.end - el.start;

                    if (el.anim === 'fade') {
                        if (lifeTime < 0.5) alpha = lifeTime / 0.5;
                        else if (globalTime > el.end - 0.5) alpha = (el.end - globalTime) / 0.5;
                    } else if (el.anim === 'slide') {
                        if (lifeTime < 0.5) {
                            alpha = lifeTime / 0.5;
                            yOffset = 50 * (1 - (lifeTime / 0.5));
                        } else if (globalTime > el.end - 0.5) {
                            alpha = (el.end - globalTime) / 0.5;
                            yOffset = -50 * (1 - ((el.end - globalTime) / 0.5));
                        }
                    }

                    ctx.globalAlpha = Math.max(0, Math.min(1, alpha));

                    if (el.type === 'text') {
                        ctx.font = 'bold 48px Arial';
                        ctx.fillStyle = '#ffffff';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.shadowColor = 'rgba(0,0,0,0.8)';
                        ctx.shadowBlur = 10;
                        ctx.fillText(el.content, el.x, el.y + yOffset);
                    }

                    ctx.restore();
                }
            });

            requestAnimationFrame(render);
        }

        // Start loop
        requestAnimationFrame(render);
    </script>
</body>
</html>
