    <script>
        // Furniture Database
        const furnitureDB = [
            { id: 'f1', name: 'Modern Sofa', price: 599, icon: '🛋️', category: 'Living Room' },
            { id: 'f2', name: 'Lounge Chair', price: 249, icon: '🪑', category: 'Living Room' },
            { id: 'f3', name: 'Dining Table', price: 399, icon: '🪚', category: 'Dining' },
            { id: 'f4', name: 'King Bed', price: 899, icon: '🛏️', category: 'Bedroom' },
            { id: 'f5', name: 'Potted Plant', price: 45, icon: '🪴', category: 'Decor' },
            { id: 'f6', name: 'Floor Lamp', price: 120, icon: '💡', category: 'Decor' }
        ];

        let roomState = []; // Stores items placed in the room
        let draggedItem = null;

        // Initialize App
        function init() {
            renderCatalog();
            setupDragAndDrop();
            loadFromURL();
        }

        // Render Catalog
        function renderCatalog() {
            const catalogDiv = document.getElementById('catalog');
            furnitureDB.forEach(item => {
                const el = document.createElement('div');
                el.className = 'furniture-item';
                el.draggable = true;
