                el.addEventListener('dragstart', (e) => {
                    draggedItem = item;
                    e.dataTransfer.setData('text/plain', item.id);
                });

                catalogDiv.appendChild(el);
            });
        }

        // Setup Drag and Drop for Virtual Room
        function setupDragAndDrop() {
            const room = document.getElementById('virtual-room');

            room.addEventListener('dragover', (e) => {
                e.preventDefault(); // Necessary to allow dropping
            });

            room.addEventListener('drop', (e) => {
                e.preventDefault();
                if (!draggedItem) return;

                // Calculate position relative to the room
                const rect = room.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;

                const instanceId = 'item_' + Date.now();

                const placedItem = {
                    instanceId: instanceId,
                    itemId: draggedItem.id,
                    x: x,
                    y: y
                };

                roomState.push(placedItem);
                renderRoom();
                updateCart();
                draggedItem = null;
            });
        }

        // Render items in the virtual room
        function renderRoom() {
            const room = document.getElementById('virtual-room');
            room.innerHTML = ''; // Clear current

            roomState.forEach(placed => {
                const itemData = furnitureDB.find(f => f.id === placed.itemId);
                if (!itemData) return;

                const el = document.createElement('div');
                el.className = 'room-item';
                el.innerHTML = itemData.icon;
                el.style.left = placed.x + 'px';
                el.style.top = placed.y + 'px';

                // Allow removing item on double click
                el.title = "Double click to remove";
                el.addEventListener('dblclick', () => {
                    roomState = roomState.filter(i => i.instanceId !== placed.instanceId);
                    renderRoom();
                    updateCart();
                });

                room.appendChild(el);
            });
        }

        // Update Shopping Cart
        function updateCart() {
            const cartDiv = document.getElementById('cart-items');
            const totalSpan = document.getElementById('total-price');
            cartDiv.innerHTML = '';

            let total = 0;

            // Group items by ID for the cart
            const cartCounts = {};
            roomState.forEach(placed => {
                cartCounts[placed.itemId] = (cartCounts[placed.itemId] || 0) + 1;
            });

            for (const [id, count] of Object.entries(cartCounts)) {
                const itemData = furnitureDB.find(f => f.id === id);
                const cost = itemData.price * count;
                total += cost;

                const el = document.createElement('div');
                el.className = 'cart-item';
                el.innerHTML = `
                    <span>${itemData.icon} ${itemData.name} x${count}</span>
                    <span>$${cost}</span>
                `;
                cartDiv.appendChild(el);
            }

            totalSpan.innerText = total;
        }

        // Clear Room
        function clearRoom() {
            roomState = [];
            renderRoom();
            updateCart();
        }

        // Save Plan (Simulated to LocalStorage)
        function savePlan() {
            localStorage.setItem('savedFurniturePlan', JSON.stringify(roomState));
            showToast("Plan saved to your personal account!");
        }

        // Share Plan (Encodes state to URL Hash)
        function sharePlan() {
            const stateString = JSON.stringify(roomState);
            const encoded = btoa(stateString);
            window.location.hash = encoded;

            // Copy to clipboard
            navigator.clipboard.writeText(window.location.href).then(() => {
                showToast("Shareable link copied to clipboard!");
            });
        }

        // Load Plan from URL Hash
        function loadFromURL() {
            const hash = window.location.hash.substring(1);
            if (hash) {
                try {
                    const decoded = atob(hash);
                    roomState = JSON.parse(decoded);
                    renderRoom();
                    updateCart();
                    showToast("Loaded shared plan!");
                } catch (e) {
                    console.error("Failed to load plan from URL");
                }
            } else {
                // Try loading from local storage if no URL hash
                const saved = localStorage.getItem('savedFurniturePlan');
                if (saved) {
                    roomState = JSON.parse(saved);
                    renderRoom();
                    updateCart();
                }
            }
        }

        // UI Toast Notification
        function showToast(message) {
            const toast = document.getElementById('toast');
            toast.innerText = message;
            toast.style.display = 'block';
            setTimeout(() => {
                toast.style.display = 'none';
            }, 3000);
        }

        // Run init on load
        window.onload = init;
    </script>
</body>
</html>
```

### Features Included:
1. **Browse Categories:** The left sidebar acts as a catalog displaying different furniture items with their prices and icons.
2. **Drag-and-Drop:** You can click and drag any item from the catalog and drop it into the central "Virtual Room". The item will be placed exactly where your mouse drops it.
3. **Shopping Cart Integration:** Every time an item is dropped into the room, it is automatically added to the shopping cart on the right. The cart groups identical items and calculates the total combined price dynamically.
4. **Remove Items:** Double-clicking an item inside the virtual room removes it from the room and deducts its price from the shopping cart.
5. **Save to Account:** Clicking "Save to Account" uses the browser's `localStorage` to save the exact coordinates and items in your room. If you refresh the page, your layout will persist.
6. **Share Links:** Clicking "Share Link" serializes the room's layout into a Base64 string, appends it to the URL hash, and copies the URL to your clipboard. If you open that URL in a new tab, it will perfectly reconstruct the room layout.

Here is a complete, executable, single-file solution using HTML, CSS, and JavaScript. 

To make the audio work without needing external MP3 files, this code uses the browser's built-in **Web Audio API** to synthesize the sounds of the notes dynamically. 

You can save the code below as an `.html` file (e.g., `musictheory.html`) and open it in any modern web browser to see it in action.

