    <script>
        // --- UI Navigation Logic ---
        function showSection(sectionId) {
            document.querySelectorAll('.section').forEach(sec => {
                sec.classList.remove('active');
            });
            document.getElementById(sectionId).classList.add('active');
        }

        // --- Web Audio API Setup (Synthesizer) ---
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();

        // Frequencies for notes
        const notes = {
            'A3': 220.00, 'B3': 246.94,
            'C4': 261.63, 'D4': 293.66, 'E4': 329.63, 'F4': 349.23, 'G4': 392.00, 'A4': 440.00, 'B4': 493.88,
            'C5': 523.25
        };

        function playTone(frequency, startTime, duration) {
            const oscillator = audioCtx.createOscillator();
            const gainNode = audioCtx.createGain();

            oscillator.type = 'sine';
            oscillator.frequency.value = frequency;

            // Envelope to prevent clicking sounds
            gainNode.gain.setValueAtTime(0, startTime);
            gainNode.gain.linearRampToValueAtTime(0.5, startTime + 0.05);
            gainNode.gain.setValueAtTime(0.5, startTime + duration - 0.05);
            gainNode.gain.linearRampToValueAtTime(0, startTime + duration);

            oscillator.connect(gainNode);
            gainNode.connect(audioCtx.destination);

            oscillator.start(startTime);
            oscillator.stop(startTime + duration);
        }

        function playScale(noteArray) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const now = audioCtx.currentTime;
            const duration = 0.4; // seconds per note

            noteArray.forEach((note, index) => {
                playTone(notes[note], now + (index * duration), duration);
            });
        }

        function playChord(noteArray) {
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const now = audioCtx.currentTime;
            const duration = 1.5; // seconds for the chord

            noteArray.forEach(note => {
                playTone(notes[note], now, duration);
            });
        }

        // --- Practice Logic ---
        function checkAnswer() {
            const checkboxes = document.querySelectorAll('.checkbox-group input[type="checkbox"]');
            const selectedNotes = [];

            checkboxes.forEach(cb => {
                if (cb.checked) selectedNotes.push(cb.value);
            });

            // The correct notes for C Major are C, E, and G
            const correctNotes = ['C', 'E', 'G'];
            const resultDiv = document.getElementById('result');

            // Check if arrays match regardless of order
            const isCorrect = selectedNotes.length === correctNotes.length && 
                              correctNotes.every(note => selectedNotes.includes(note));

            if (isCorrect) {
                resultDiv.innerHTML = '<span class="correct">Correct! A C Major chord consists of the root (C), major third (E), and perfect fifth (G).</span>';
                playChord(['C4', 'E4', 'G4']); // Play it as a reward
            } else {
                resultDiv.innerHTML = '<span class="incorrect">Incorrect. Hint: A C Major chord needs a root, a major third, and a perfect fifth. Try again!</span>';
            }
        }
    </script>
</body>
</html>
```

### Features Included:
1. **Navigation & Structure:** A clean, single-page application feel using CSS and JavaScript to toggle between "Scales", "Chords", and "Practice" sections.
2. **Audio Synthesis:** Uses the browser's native `AudioContext` to generate sine waves. This means you don't need to host MP3 files; the browser generates the exact frequencies for the notes (e.g., C4 = 261.63 Hz).
3. **Scales Demonstration:** Plays notes sequentially (arpeggiated) to demonstrate Major and Minor scales.
