        const annoX = document.getElementById('annoX');
        const annoY = document.getElementById('annoY');
        const annoSize = document.getElementById('annoSize');
        const annoColor = document.getElementById('annoColor');

        const addAnnoBtn = document.getElementById('addAnnoBtn');
        const clearAnnoBtn = document.getElementById('clearAnnoBtn');
        const downloadBtn = document.getElementById('downloadBtn');

        // Handle File Upload
        fileInput.addEventListener('change', (e) => {
            const files = Array.from(e.target.files);
            if (files.length === 0) return;

            files.forEach(file => {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const img = new Image();
                    img.onload = () => {
                        imagesData.push({
                            file: file,
                            name: file.name,
                            dataURL: event.target.result,
                            imgObj: img,
                            annotations: []
                        });
                        renderImageList();
                        if (currentIndex === -1) {
                            selectImage(0);
                        }
                    };
                    img.src = event.target.result;
                };
                reader.readAsDataURL(file);
