        });

        // Render Image List in Sidebar
        function renderImageList() {
            imageList.innerHTML = '';
            imagesData.forEach((data, index) => {
                const li = document.createElement('li');
                li.textContent = data.name + ` (${data.annotations.length} annos)`;
                if (index === currentIndex) {
                    li.classList.add('active');
                }
                li.addEventListener('click', () => selectImage(index));
                imageList.appendChild(li);
            });
        }

        // Select an image to display on canvas
        function selectImage(index) {
            currentIndex = index;
            renderImageList();
            const data = imagesData[currentIndex];
            currentImageTitle.textContent = data.name;

            // Set canvas dimensions to match image
            canvas.width = data.imgObj.width;
            canvas.height = data.imgObj.height;

            drawCanvas();
