        // Draw image and its annotations on canvas
        function drawCanvas() {
            if (currentIndex === -1) return;
            const data = imagesData[currentIndex];

            // Draw original image
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.drawImage(data.imgObj, 0, 0);

            // Draw annotations
            data.annotations.forEach(anno => {
                ctx.font = `${anno.size}px Arial`;
                ctx.fillStyle = anno.color;
                ctx.fillText(anno.text, anno.x, anno.y);
            });
