        canvas.addEventListener('click', (e) => {
            if (currentIndex === -1) return;
            // Calculate actual coordinates based on canvas scaling
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / rect.width;
            const scaleY = canvas.height / rect.height;

            const x = (e.clientX - rect.left) * scaleX;
            const y = (e.clientY - rect.top) * scaleY;

            annoX.value = Math.round(x);
            annoY.value = Math.round(y);
        });

        // Add Annotation Button
        addAnnoBtn.addEventListener('click', () => {
            if (currentIndex === -1) {
                alert("Please select an image first.");
                return;
            }
            if (!annoText.value.trim()) {
                alert("Please enter some text.");
                return;
            }

            const newAnno = {
                text: annoText.value,
                x: parseInt(annoX.value),
                y: parseInt(annoY.value),
                size: parseInt(annoSize.value),
                color: annoColor.value
            };

            imagesData[currentIndex].annotations.push(newAnno);
            drawCanvas();
            renderImageList(); // Update annotation count in list
        });

        // Clear Annotations Button
        clearAnnoBtn.addEventListener('click', () => {
            if (currentIndex === -1) return;
            imagesData[currentIndex].annotations = [];
            drawCanvas();
            renderImageList();
        });

        // Batch Download (ZIP)
        downloadBtn.addEventListener('click', async () => {
            if (imagesData.length === 0) {
                alert("No images to download.");
                return;
            }

            downloadBtn.textContent = "Generating ZIP...";
            downloadBtn.disabled = true;

            const zip = new JSZip();
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');

            for (let i = 0; i < imagesData.length; i++) {
                const data = imagesData[i];

                // Setup temp canvas
                tempCanvas.width = data.imgObj.width;
                tempCanvas.height = data.imgObj.height;

                // Draw image
                tempCtx.clearRect(0, 0, tempCanvas.width, tempCanvas.height);
                tempCtx.drawImage(data.imgObj, 0, 0);

                // Draw annotations
                data.annotations.forEach(anno => {
                    tempCtx.font = `${anno.size}px Arial`;
                    tempCtx.fillStyle = anno.color;
                    tempCtx.fillText(anno.text, anno.x, anno.y);
                });

                // Convert to blob
                const blob = await new Promise(resolve => tempCanvas.toBlob(resolve, 'image/png'));

                // Add to zip (prefix with annotated_ to distinguish)
                zip.file(`annotated_${data.name.split('.')[0]}.png`, blob);
            }

            // Generate ZIP and trigger download
            zip.generateAsync({ type: "blob" }).then(function(content) {
                const url = URL.createObjectURL(content);
                const a = document.createElement('a');
                a.href = url;
                a.download = "annotated_images.zip";
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                URL.revokeObjectURL(url);

                downloadBtn.textContent = "Batch Download (ZIP)";
                downloadBtn.disabled = false;
            });
        });
    </script>
