</head>
<body class="bg-gray-100 text-gray-800 font-sans p-6">

    <div class="max-w-6xl mx-auto">
        <h1 class="text-3xl font-bold text-center mb-8 text-blue-600">Inventory Management System</h1>

        <div class="grid grid-cols-1 md:grid-cols-3 gap-6">
            <!-- Form Section -->
            <div class="bg-white p-6 rounded-lg shadow-md col-span-1 h-fit">
                <h2 class="text-xl font-semibold mb-4" id="formTitle">Add New Product</h2>
                <form id="inventoryForm">
                    <input type="hidden" id="productId">

                    <div class="mb-4">
                        <label class="block text-sm font-medium text-gray-700 mb-1">Product Name</label>
                        <input type="text" id="name" required class="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>

                    <div class="mb-4">
                        <label class="block text-sm font-medium text-gray-700 mb-1">Price ($)</label>
                        <input type="number" id="price" step="0.01" min="0" required class="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>

                    <div class="mb-4">
                        <label class="block text-sm font-medium text-gray-700 mb-1">Inventory Quantity</label>
                        <input type="number" id="quantity" min="0" required class="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>

                    <div class="mb-6">
                        <label class="block text-sm font-medium text-gray-700 mb-1">Low Stock Threshold</label>
                        <input type="number" id="threshold" min="0" required class="w-full border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500">
                        <p class="text-xs text-gray-500 mt-1">Alert triggers if quantity falls below this number.</p>
                    </div>

                    <div class="flex gap-2">
                        <button type="submit" id="submitBtn" class="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition">Add Product</button>
                        <button type="button" id="cancelBtn" class="w-full bg-gray-400 text-white py-2 rounded hover:bg-gray-500 transition hidden">Cancel</button>
                    </div>
                </form>
            </div>

            <!-- Inventory Table Section -->
            <div class="bg-white p-6 rounded-lg shadow-md col-span-1 md:col-span-2 overflow-x-auto">
                <h2 class="text-xl font-semibold mb-4">Current Inventory</h2>
                <table class="w-full text-left border-collapse">
                    <thead>
                        <tr class="bg-gray-200 text-gray-700">
                            <th class="p-3 border-b">Name</th>
                            <th class="p-3 border-b">Price</th>
                            <th class="p-3 border-b">Quantity</th>
                            <th class="p-3 border-b">Status</th>
                            <th class="p-3 border-b text-center">Actions</th>
                        </tr>
                    </thead>
                    <tbody id="inventoryTableBody">
                        <!-- Rows will be populated by JavaScript -->
                    </tbody>
                </table>
                <div id="emptyState" class="text-center text-gray-500 py-6 hidden">
                    No products in inventory. Add one to get started!
                </div>
            </div>
        </div>
    </div>

    <script>
        // Initialize inventory from localStorage or use an empty array
        let inventory = JSON.parse(localStorage.getItem('inventoryData')) || [];
        let isEditing = false;

        // DOM Elements
        const form = document.getElementById('inventoryForm');
        const tableBody = document.getElementById('inventoryTableBody');
        const emptyState = document.getElementById('emptyState');
        const formTitle = document.getElementById('formTitle');
        const submitBtn = document.getElementById('submitBtn');
        const cancelBtn = document.getElementById('cancelBtn');

        // Form Inputs
        const idInput = document.getElementById('productId');
        const nameInput = document.getElementById('name');
        const priceInput = document.getElementById('price');
        const quantityInput = document.getElementById('quantity');
        const thresholdInput = document.getElementById('threshold');

        // Render the table
        function renderTable() {
            tableBody.innerHTML = '';

            if (inventory.length === 0) {
                emptyState.classList.remove('hidden');
            } else {
                emptyState.classList.add('hidden');

                inventory.forEach(product => {
                    const isLowStock = product.quantity <= product.threshold;
                    const row = document.createElement('tr');

                    // Apply warning class if low stock
                    if (isLowStock) {
                        row.className = 'low-stock-row border-b';
                    } else {
                        row.className = 'border-b hover:bg-gray-50';
                    }

                    row.innerHTML = `
                        <td class="p-3 font-medium">${product.name}</td>
                        <td class="p-3">$${parseFloat(product.price).toFixed(2)}</td>
                        <td class="p-3 font-bold ${isLowStock ? 'text-red-600' : 'text-green-600'}">${product.quantity}</td>
                        <td class="p-3">
                            ${isLowStock 
                                ? '<span class="bg-red-500 text-white text-xs px-2 py-1 rounded-full font-semibold">Low Stock Alert</span>' 
                                : '<span class="bg-green-500 text-white text-xs px-2 py-1 rounded-full font-semibold">In Stock</span>'}
                        </td>
                        <td class="p-3 text-center">
                            <button onclick="editProduct('${product.id}')" class="text-blue-500 hover:text-blue-700 mr-2">Edit</button>
                            <button onclick="deleteProduct('${product.id}')" class="text-red-500 hover:text-red-700">Delete</button>
                        </td>
                    `;
                    tableBody.appendChild(row);
                });
            }

            // Save to local storage
            localStorage.setItem('inventoryData', JSON.stringify(inventory));
        }

        // Handle Form Submission (Add or Update)
        form.addEventListener('submit', function(e) {
            e.preventDefault();

            const productData = {
                id: isEditing ? idInput.value : Date.now().toString(),
                name: nameInput.value,
                price: parseFloat(priceInput.value),
                quantity: parseInt(quantityInput.value),
                threshold: parseInt(thresholdInput.value)
            };

            if (isEditing) {
                const index = inventory.findIndex(p => p.id === productData.id);
                if (index !== -1) inventory[index] = productData;
            } else {
                inventory.push(productData);
            }

            resetForm();
            renderTable();
        });

        // Edit Product
        window.editProduct = function(id) {
            const product = inventory.find(p => p.id === id);
            if (!product) return;

            idInput.value = product.id;
            nameInput.value = product.name;
            priceInput.value = product.price;
            quantityInput.value = product.quantity;
            thresholdInput.value = product.threshold;

            isEditing = true;
            formTitle.innerText = "Edit Product";
            submitBtn.innerText = "Update Product";
            submitBtn.classList.replace('bg-blue-600', 'bg-green-600');
            submitBtn.classList.replace('hover:bg-blue-700', 'hover:bg-green-700');
            cancelBtn.classList.remove('hidden');
        };

        // Delete Product
        window.deleteProduct = function(id) {
            if (confirm("Are you sure you want to delete this product?")) {
                inventory = inventory.filter(p => p.id !== id);
                renderTable();
            }
        };

        // Reset Form
        function resetForm() {
            form.reset();
            isEditing = false;
            idInput.value = '';
            formTitle.innerText = "Add New Product";
            submitBtn.innerText = "Add Product";
            submitBtn.classList.replace('bg-green-600', 'bg-blue-600');
            submitBtn.classList.replace('hover:bg-green-700', 'hover:bg-blue-700');
            cancelBtn.classList.add('hidden');
        }

        cancelBtn.addEventListener('click', resetForm);

        // Initial Render
        renderTable();
    </script>
</body>
</html>
```

### Features Included:
1. **Add Products**: Fill out the form on the left to add items to the inventory.
2. **Edit Products**: Click the "Edit" button on any row. The form will switch to "Edit Mode", allowing you to update the name, price, quantity, or threshold.
3. **Low Inventory Alert**: If a product's `Inventory Quantity` is less than or equal to its `Low Stock Threshold`, the system automatically:
   - Highlights the row with a subtle red pulsing animation.
   - Changes the quantity text to red.
   - Displays a red "Low Stock Alert" badge.
4. **Data Persistence**: The system uses the browser's `localStorage`. If you refresh the page or close the browser, your inventory data will remain intact.

