    <script>
        // Simulated Data
        let devices = [
            {
                id: 1,
                name: "CNC Milling Machine",
                cycleType: "days",
                cycleValue: 30,
                lastMaintenanceDate: new Date(Date.now() - 25 * 86400000).toISOString().split('T')[0], // 25 days ago
                currentHours: 0,
                history: [
                    { date: new Date(Date.now() - 25 * 86400000).toISOString().split('T')[0], personnel: "John Doe", consumables: "Coolant, Lubricant" }
                ]
            },
            {
                id: 2,
                name: "Air Compressor",
                cycleType: "days",
                cycleValue: 90,
                lastMaintenanceDate: new Date(Date.now() - 95 * 86400000).toISOString().split('T')[0], // 95 days ago (Overdue)
                currentHours: 0,
                history: [
                    { date: new Date(Date.now() - 95 * 86400000).toISOString().split('T')[0], personnel: "Jane Smith", consumables: "Air Filter" }
                ]
            },
            {
                id: 3,
                name: "Forklift",
                cycleType: "hours",
                cycleValue: 500,
                lastMaintenanceDate: new Date(Date.now() - 10 * 86400000).toISOString().split('T')[0],
                currentHours: 480, // Close to 500
                history: [
                    { date: new Date(Date.now() - 10 * 86400000).toISOString().split('T')[0], personnel: "Mike Johnson", consumables: "Hydraulic Fluid", hoursAtMaintenance: 0 }
                ]
            }
        ];

        // Utility: Calculate Status
        function getDeviceStatus(device) {
            if (device.cycleType === 'days') {
                const lastDate = new Date(device.lastMaintenanceDate);
                const nextDate = new Date(lastDate.getTime() + device.cycleValue * 86400000);
                const today = new Date();
                const diffDays = Math.ceil((nextDate - today) / 86400000);

                if (diffDays < 0) return { color: 'red', text: `Overdue by ${Math.abs(diffDays)} days` };
                if (diffDays <= 7) return { color: 'yellow', text: `Due in ${diffDays} days` };
                return { color: 'green', text: `Normal (${diffDays} days left)` };
            } else {
                // Hours logic
                let lastMaintenanceHours = 0;
                if (device.history.length > 0 && device.history[device.history.length - 1].hoursAtMaintenance !== undefined) {
                    lastMaintenanceHours = device.history[device.history.length - 1].hoursAtMaintenance;
                }
                const hoursSinceLast = device.currentHours - lastMaintenanceHours;
                const hoursLeft = device.cycleValue - hoursSinceLast;

                if (hoursLeft < 0) return { color: 'red', text: `Overdue by ${Math.abs(hoursLeft)} hours` };
                if (hoursLeft <= (device.cycleValue * 0.1)) return { color: 'yellow', text: `Due in ${hoursLeft} hours` }; // 10% threshold
                return { color: 'green', text: `Normal (${hoursLeft} hours left)` };
            }
        }

        // Render Dashboard
        function renderDashboard() {
            const grid = document.getElementById('deviceGrid');
            grid.innerHTML = '';

            devices.forEach(dev => {
