        }

        function closeModal(modalId) {
            document.getElementById(modalId).style.display = 'none';
        }

        function toggleCycleInput() {
            const type = document.getElementById('devCycleType').value;
            document.getElementById('cycleLabel').innerText = type === 'days' ? 'Cycle Value (Days)' : 'Cycle Value (Hours)';
            document.getElementById('currentHoursGroup').style.display = type === 'hours' ? 'block' : 'none';
        }

        // Add Device Logic
        function handleAddDevice(e) {
            e.preventDefault();
            const newDevice = {
                id: Date.now(),
                name: document.getElementById('devName').value,
                cycleType: document.getElementById('devCycleType').value,
                cycleValue: parseInt(document.getElementById('devCycleValue').value),
                lastMaintenanceDate: document.getElementById('devLastDate').value,
                currentHours: parseInt(document.getElementById('devCurrentHours').value) || 0,
                history: []
            };
            devices.push(newDevice);
            closeModal('addDeviceModal');
            renderDashboard();
        }

        // Open Device Details
        function openDeviceDetails(id) {
            const device = devices.find(d => d.id === id);
            if (!device) return;

            document.getElementById('detailName').innerText = device.name;
            document.getElementById('detailInfo').innerHTML = `
                <strong>Cycle:</strong> ${device.cycleValue} ${device.cycleType} <br>
                <strong>Last Maintenance:</strong> ${device.lastMaintenanceDate}
                ${device.cycleType === 'hours' ? `<br><strong>Current Hours:</strong> ${device.currentHours}` : ''}
            `;

            // Render History
            const historyList = document.getElementById('historyList');
            historyList.innerHTML = '';
            if (device.history.length === 0) {
                historyList.innerHTML = '<li>No maintenance records found.</li>';
            } else {
                // Sort history descending by date
                const sortedHistory = [...device.history].sort((a, b) => new Date(b.date) - new Date(a.date));
                sortedHistory.forEach(record => {
                    historyList.innerHTML += `
                        <li class="history-item">
                            <strong>Date:</strong> ${record.date} <br>
                            <strong>Personnel:</strong> ${record.personnel} <br>
                            <strong>Consumables:</strong> ${record.consumables}
                            ${record.hoursAtMaintenance !== undefined ? `<br><strong>Hours:</strong> ${record.hoursAtMaintenance}` : ''}
                        </li>
                    `;
                });
            }

            // Setup Add Record Form
            document.getElementById('addRecordForm').reset();
            document.getElementById('recordDate').valueAsDate = new Date();
            document.getElementById('recordDeviceId').value = device.id;
            document.getElementById('recordHoursGroup').style.display = device.cycleType === 'hours' ? 'block' : 'none';
            if(device.cycleType === 'hours') {
                document.getElementById('recordHours').value = device.currentHours;
            }

            document.getElementById('deviceDetailsModal').style.display = 'flex';
        }

        // Add Maintenance Record Logic
        function handleAddRecord(e) {
            e.preventDefault();
            const deviceId = parseInt(document.getElementById('recordDeviceId').value);
            const device = devices.find(d => d.id === deviceId);

            const newRecord = {
                date: document.getElementById('recordDate').value,
                personnel: document.getElementById('recordPersonnel').value,
                consumables: document.getElementById('recordConsumables').value
            };

            if (device.cycleType === 'hours') {
                newRecord.hoursAtMaintenance = parseInt(document.getElementById('recordHours').value);
                device.currentHours = newRecord.hoursAtMaintenance; // Update current hours to match maintenance
            }

            device.history.push(newRecord);

            // Update last maintenance date if the new record is newer
            if (new Date(newRecord.date) >= new Date(device.lastMaintenanceDate)) {
                device.lastMaintenanceDate = newRecord.date;
            }

            closeModal('deviceDetailsModal');
            renderDashboard();
        }

        // Initial Render
        renderDashboard();
    </script>
</body>
</html>
