        input { padding: 5px; border-radius: 4px; border: 1px solid #ccc; }
        textarea { width: 100%; height: 100px; margin-top: 10px; font-family: monospace; }
        .instructions { font-size: 0.9em; color: #bdc3c7; margin-top: 20px; }
    </style>
</head>
<body>

    <div id="controls">
        <button id="btn-edit" class="active" onclick="setMode('edit')">Editor Mode</button>
        <button id="btn-play" onclick="setMode('play')">Test / Play</button>
        <div style="border-left: 2px solid #7f8c8d; margin: 0 10px;"></div>
        <button onclick="selectTool('player')">Place Player</button>
        <button onclick="selectTool('enemy')">Place Enemy</button>
        <button onclick="selectTool('wall')">Place Wall</button>
        <button onclick="selectTool('goal')">Place Goal</button>
    </div>

    <div id="main-area">
        <canvas id="gameCanvas" width="800" height="600"></canvas>

        <div id="sidebar">
            <h3>Properties</h3>
            <div id="properties-panel" style="display: none;">
                <div class="prop-group">
                    <label>Type: <span id="prop-type"></span></label>
                </div>
                <div class="prop-group">
                    <label>X Position</label>
                    <input type="number" id="prop-x" onchange="updateProperty('x')">
                </div>
                <div class="prop-group">
                    <label>Y Position</label>
                    <input type="number" id="prop-y" onchange="updateProperty('y')">
                </div>
                <div class="prop-group">
                    <label>Width</label>
                    <input type="number" id="prop-w" onchange="updateProperty('w')">
                </div>
                <div class="prop-group">
                    <label>Height</label>
                    <input type="number" id="prop-h" onchange="updateProperty('h')">
                </div>
                <button onclick="deleteSelected()" style="background: #e74c3c; margin-top: 10px;">Delete Object</button>
            </div>
            <div id="no-selection">Select an object to edit.</div>

            <hr style="width: 100%; border-color: #7f8c8d;">
            <h3>Save / Load</h3>
            <button onclick="exportLevel()">Export Level</button>
            <button onclick="importLevel()">Import Level</button>
            <textarea id="level-data" placeholder="Level JSON data will appear here..."></textarea>

            <div class="instructions">
                <b>Editor:</b> Select a tool, click canvas to place. Click objects to drag or edit properties.<br><br>
                <b>Play:</b> WASD to move. Mouse click to shoot. Reach the Goal to win!
            </div>
        </div>
    </div>

<script>
    const canvas = document.getElementById('gameCanvas');
    const ctx = canvas.getContext('2d');

    // Game State
    let mode = 'edit'; // 'edit' or 'play'
    let currentTool = 'select';
    let entities = [];
    let bullets = [];
    let selectedEntity = null;
    let isDragging = false;
    let dragOffsetX = 0;
    let dragOffsetY = 0;

    // Play Mode State
    let keys = {};
    let playerRef = null;
    let gameState = 'playing'; // playing, won, lost

    // Entity Definitions
    const COLORS = { player: '#3498db', enemy: '#e74c3c', wall: '#7f8c8d', goal: '#f1c40f' };

    class Entity {
        constructor(type, x, y) {
            this.id = Math.random().toString(36).substr(2, 9);
            this.type = type;
            this.x = x;
            this.y = y;
            this.w = type === 'wall' ? 100 : 30;
            this.h = type === 'wall' ? 20 : 30;
            this.speed = type === 'player' ? 4 : (type === 'enemy' ? 1.5 : 0);
            this.hp = type === 'enemy' ? 3 : 1;
        }
        draw(ctx) {
            ctx.fillStyle = COLORS[this.type];
            ctx.fillRect(this.x, this.y, this.w, this.h);
            if (selectedEntity === this && mode === 'edit') {
                ctx.strokeStyle = '#2ecc71';
                ctx.lineWidth = 3;
                ctx.strokeRect(this.x - 2, this.y - 2, this.w + 4, this.h + 4);
            }
        }
    }

    class Bullet {
        constructor(x, y, vx, vy) {
            this.x = x; this.y = y;
            this.vx = vx; this.vy = vy;
            this.radius = 5;
            this.active = true;
        }
        update() {
            this.x += this.vx;
            this.y += this.vy;
        }
        draw(ctx) {
            ctx.fillStyle = '#f39c12';
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // --- UI & Editor Logic ---
    function setMode(newMode) {
        mode = newMode;
        document.getElementById('btn-edit').classList.toggle('active', mode === 'edit');
        document.getElementById('btn-play').classList.toggle('active', mode === 'play');

        if (mode === 'play') {
            selectedEntity = null;
            updatePropertiesPanel();
            playerRef = entities.find(e => e.type === 'player');
            bullets = [];
            gameState = 'playing';
            // Reset enemy HP
            entities.forEach(e => { if(e.type === 'enemy') e.hp = 3; });
        }
    }

    function selectTool(tool) {
        currentTool = tool;
        setMode('edit');
    }

    function getEntityAt(x, y) {
        for (let i = entities.length - 1; i >= 0; i--) {
            let e = entities[i];
            if (x >= e.x && x <= e.x + e.w && y >= e.y && y <= e.y + e.h) return e;
        }
        return null;
    }

    canvas.addEventListener('mousedown', (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        if (mode === 'edit') {
            let clickedEntity = getEntityAt(mx, my);
            if (clickedEntity) {
                selectedEntity = clickedEntity;
                isDragging = true;
                dragOffsetX = mx - clickedEntity.x;
                dragOffsetY = my - clickedEntity.y;
                updatePropertiesPanel();
            } else {
                if (currentTool !== 'select') {
                    // Enforce single player
                    if (currentTool === 'player' && entities.some(ent => ent.type === 'player')) {
                        alert("Only one player allowed!");
                        return;
                    }
                    let newEnt = new Entity(currentTool, mx - 15, my - 15);
                    entities.push(newEnt);
                    selectedEntity = newEnt;
                    updatePropertiesPanel();
                    currentTool = 'select'; // Reset tool
                } else {
                    selectedEntity = null;
                    updatePropertiesPanel();
                }
            }
        } else if (mode === 'play' && playerRef && gameState === 'playing') {
            // Shoot
            let dx = mx - (playerRef.x + playerRef.w/2);
            let dy = my - (playerRef.y + playerRef.h/2);
            let mag = Math.sqrt(dx*dx + dy*dy);
            let speed = 8;
            bullets.push(new Bullet(playerRef.x + playerRef.w/2, playerRef.y + playerRef.h/2, (dx/mag)*speed, (dy/mag)*speed));
        }
    });

    canvas.addEventListener('mousemove', (e) => {
        if (mode === 'edit' && isDragging && selectedEntity) {
            const rect = canvas.getBoundingClientRect();
            selectedEntity.x = e.clientX - rect.left - dragOffsetX;
            selectedEntity.y = e.clientY - rect.top - dragOffsetY;
            updatePropertiesPanel();
        }
    });

    canvas.addEventListener('mouseup', () => { isDragging = false; });

    // --- Properties Panel ---
    function updatePropertiesPanel() {
        const panel = document.getElementById('properties-panel');
        const noSel = document.getElementById('no-selection');
        if (selectedEntity) {
            panel.style.display = 'block';
            noSel.style.display = 'none';
            document.getElementById('prop-type').innerText = selectedEntity.type.toUpperCase();
            document.getElementById('prop-x').value = Math.round(selectedEntity.x);
            document.getElementById('prop-y').value = Math.round(selectedEntity.y);
            document.getElementById('prop-w').value = selectedEntity.w;
            document.getElementById('prop-h').value = selectedEntity.h;
        } else {
            panel.style.display = 'none';
            noSel.style.display = 'block';
        }
    }

    function updateProperty(prop) {
        if (!selectedEntity) return;
        selectedEntity[prop] = parseFloat(document.getElementById(`prop-${prop}`).value);
    }

    function deleteSelected() {
        if (!selectedEntity) return;
        entities = entities.filter(e => e !== selectedEntity);
        selectedEntity = null;
        updatePropertiesPanel();
    }

    // --- Save / Load ---
    function exportLevel() {
        const data = JSON.stringify(entities);
        document.getElementById('level-data').value = data;
    }

    function importLevel() {
        try {
            const data = document.getElementById('level-data').value;
            const parsed = JSON.parse(data);
            entities = parsed.map(e => Object.assign(new Entity(e.type, e.x, e.y), e));
            selectedEntity = null;
            updatePropertiesPanel();
            alert("Level loaded successfully!");
        } catch (err) {
            alert("Invalid Level JSON!");
        }
    }

    // --- Play Mode Logic ---
    window.addEventListener('keydown', e => keys[e.key.toLowerCase()] = true);
    window.addEventListener('keyup', e => keys[e.key.toLowerCase()] = false);

    function checkCollision(r1, r2) {
        return r1.x < r2.x + r2.w && r1.x + r1.w > r2.x &&
               r1.y < r2.y + r2.h && r1.y + r1.h > r2.y;
    }

    function updatePlayMode() {
        if (gameState !== 'playing') return;

        // Player Movement
        if (playerRef) {
            let oldX = playerRef.x;
            let oldY = playerRef.y;

            if (keys['w']) playerRef.y -= playerRef.speed;
            if (keys['s']) playerRef.y += playerRef.speed;
            if (keys['a']) playerRef.x -= playerRef.speed;
            if (keys['d']) playerRef.x += playerRef.speed;

            // Wall Collisions for Player
            entities.filter(e => e.type === 'wall').forEach(wall => {
                if (checkCollision(playerRef, wall)) {
                    playerRef.x = oldX;
                    playerRef.y = oldY;
                }
            });

            // Goal Collision
            entities.filter(e => e.type === 'goal').forEach(goal => {
                if (checkCollision(playerRef, goal)) gameState = 'won';
            });

            // Enemy Collision (Lose)
            entities.filter(e => e.type === 'enemy').forEach(enemy => {
                if (checkCollision(playerRef, enemy)) gameState = 'lost';
            });
        }

        // Enemy AI (Simple tracking)
        entities.filter(e => e.type === 'enemy').forEach(enemy => {
            if (playerRef) {
                let dx = playerRef.x - enemy.x;
                let dy = playerRef.y - enemy.y;
                let mag = Math.sqrt(dx*dx + dy*dy);
                if (mag > 0) {
                    enemy.x += (dx/mag) * enemy.speed;
                    enemy.y += (dy/mag) * enemy.speed;
                }
            }
        });

        // Bullets
        bullets.forEach(b => {
            b.update();
            // Bullet hits wall
            entities.filter(e => e.type === 'wall').forEach(wall => {
                if (b.x > wall.x && b.x < wall.x + wall.w && b.y > wall.y && b.y < wall.y + wall.h) b.active = false;
            });
            // Bullet hits enemy
            entities.filter(e => e.type === 'enemy').forEach(enemy => {
                if (b.x > enemy.x && b.x < enemy.x + enemy.w && b.y > enemy.y && b.y < enemy.y + enemy.h) {
                    b.active = false;
                    enemy.hp--;
                }
            });
        });

        // Cleanup dead enemies and bullets
        entities = entities.filter(e => e.type !== 'enemy' || e.hp > 0);
        bullets = bullets.filter(b => b.active && b.x > 0 && b.x < canvas.width && b.y > 0 && b.y < canvas.height);
    }

    // --- Main Loop ---
    function loop() {
        // Clear Canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        if (mode === 'play') {
            updatePlayMode();
        }

        // Draw Entities
        entities.forEach(e => e.draw(ctx));
        bullets.forEach(b => b.draw(ctx));

        // Draw Game State Overlays
        if (mode === 'play') {
            if (gameState === 'won') {
                ctx.fillStyle = 'rgba(46, 204, 113, 0.8)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = 'white';
                ctx.font = '40px Arial';
                ctx.fillText("LEVEL CLEARED!", 250, 300);
            } else if (gameState === 'lost') {
                ctx.fillStyle = 'rgba(231, 76, 60, 0.8)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = 'white';
                ctx.font = '40px Arial';
                ctx.fillText("GAME OVER", 280, 300);
            }
        }

        requestAnimationFrame(loop);
    }

    // Start Loop
    loop();
</script>
</body>
</html>
```

Building a fully-featured, drag-and-drop modular synthesizer from scratch is a complex task that typically requires a robust frontend framework (like React or Vue) and a dedicated node-graph library. However, we can build a **functional, vanilla HTML/JS prototype** that demonstrates the core mechanics: creating Web Audio API nodes, dragging them around a workspace, connecting them visually and audibly, and exporting the result.

Below is a complete, executable single-file web application. Save this code as an `.html` file and open it in any modern web browser.

### `modular-synth.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Web Modular Synth</title>
    <style>
        body { margin: 0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #1e1e1e; color: #fff; overflow: hidden; }
        #toolbar { padding: 10px; background: #333; display: flex; gap: 10px; z-index: 10; position: relative; }
        button { padding: 8px 12px; background: #555; color: white; border: none; border-radius: 4px; cursor: pointer; }
        button:hover { background: #777; }
        #workspace { position: relative; width: 100vw; height: calc(100vh - 50px); overflow: hidden; }
        svg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 1; }

        .module { position: absolute; width: 150px; background: #2d2d2d; border: 1px solid #555; border-radius: 6px; padding: 10px; z-index: 2; box-shadow: 0 4px 6px rgba(0,0,0,0.3); user-select: none; }
        .module-header { font-weight: bold; margin-bottom: 10px; cursor: grab; border-bottom: 1px solid #555; padding-bottom: 5px; }
        .module-header:active { cursor: grabbing; }
        .control { margin-bottom: 10px; font-size: 12px; }
        .control input { width: 100%; }

        .port { width: 12px; height: 12px; background: #aaa; border-radius: 50%; cursor: crosshair; position: absolute; border: 2px solid #2d2d2d; }
        .port:hover { background: #fff; }
        .port.in { left: -8px; top: 50%; transform: translateY(-50%); }
        .port.out { right: -8px; top: 50%; transform: translateY(-50%); }
        .port.active { background: #4caf50; }
    </style>
</head>
<body>

<div id="toolbar">
    <button onclick="addOscillator()">+ Oscillator</button>
    <button onclick="addFilter()">+ Lowpass Filter</button>
    <button id="recordBtn" onclick="toggleRecording()" style="margin-left: auto; background: #8b0000;">Start Recording</button>
</div>

<div id="workspace">
    <svg id="connections"></svg>
    <!-- Master Output Module -->
    <div class="module" id="master-out" style="left: 600px; top: 200px;">
        <div class="module-header">Master Output</div>
        <div class="port in" data-node-id="master"></div>
    </div>
</div>

<script>
    // --- Web Audio API Setup ---
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const masterGain = audioCtx.createGain();
    masterGain.connect(audioCtx.destination);

    // Recording Setup
    const destStream = audioCtx.createMediaStreamDestination();
    masterGain.connect(destStream);
    let mediaRecorder;
    let recordedChunks = [];
    let isRecording = false;

    // --- State Management ---
    const nodes = {
        'master': { audioNode: masterGain, element: document.getElementById('master-out') }
    };
    let connectionState = { fromId: null, fromElement: null };
    let nodeIdCounter = 0;

    // --- UI & Dragging Logic ---
    let draggedElement = null;
    let offsetX = 0, offsetY = 0;

    document.addEventListener('mousedown', (e) => {
        if (e.target.classList.contains('module-header')) {
            draggedElement = e.target.parentElement;
            offsetX = e.clientX - draggedElement.offsetLeft;
            offsetY = e.clientY - draggedElement.offsetTop;
        }
    });

    document.addEventListener('mousemove', (e) => {
        if (draggedElement) {
            draggedElement.style.left = `${e.clientX - offsetX}px`;
            draggedElement.style.top = `${e.clientY - offsetY}px`;
            updateLines();
        }
    });

    document.addEventListener('mouseup', () => { draggedElement = null; });

    // --- Module Creation ---
    function createModuleUI(id, title, controlsHtml, hasIn, hasOut) {
        const mod = document.createElement('div');
        mod.className = 'module';
        mod.id = id;
        mod.style.left = `${Math.random() * 200 + 50}px`;
        mod.style.top = `${Math.random() * 200 + 50}px`;

        let html = `<div class="module-header">${title}</div>`;
        if (hasIn) html += `<div class="port in" data-node-id="${id}"></div>`;
        if (hasOut) html += `<div class="port out" data-node-id="${id}"></div>`;
        html += controlsHtml;

        mod.innerHTML = html;
        document.getElementById('workspace').appendChild(mod);

        // Port click listeners
        mod.querySelectorAll('.port').forEach(port => {
            port.addEventListener('click', (e) => handlePortClick(e, port, id));
        });

        return mod;
    }

    function addOscillator() {
        const id = `osc_${nodeIdCounter++}`;
        const osc = audioCtx.createOscillator();
        osc.type = 'sawtooth';
        osc.start();

        const controls = `
            <div class="control">
                <label>Freq: <span id="${id}_val">440</span>Hz</label>
                <input type="range" min="50" max="2000" value="440" oninput="updateParam('${id}', 'frequency', this.value)">
            </div>
        `;
        const el = createModuleUI(id, 'Oscillator', controls, false, true);
        nodes[id] = { audioNode: osc, element: el, connections: [] };
    }

    function addFilter() {
        const id = `filter_${nodeIdCounter++}`;
        const filter = audioCtx.createBiquadFilter();
        filter.type = 'lowpass';
        filter.frequency.value = 1000;

        const controls = `
            <div class="control">
                <label>Cutoff: <span id="${id}_val">1000</span>Hz</label>
                <input type="range" min="100" max="5000" value="1000" oninput="updateParam('${id}', 'frequency', this.value)">
            </div>
        `;
        const el = createModuleUI(id, 'Filter', controls, true, true);
        nodes[id] = { audioNode: filter, element: el, connections: [] };
    }

    window.updateParam = function(id, param, value) {
        document.getElementById(`${id}_val`).innerText = value;
        nodes[id].audioNode[param].setValueAtTime(value, audioCtx.currentTime);
    };

    // --- Connection Logic ---
    function handlePortClick(e, port, id) {
        e.stopPropagation();
        if (audioCtx.state === 'suspended') audioCtx.resume();

        if (port.classList.contains('out')) {
            // Start connection
            if (connectionState.fromElement) connectionState.fromElement.classList.remove('active');
            connectionState = { fromId: id, fromElement: port };
            port.classList.add('active');
        } else if (port.classList.contains('in') && connectionState.fromId) {
            // Complete connection
            const fromNode = nodes[connectionState.fromId];
            const toNode = nodes[id];

            fromNode.audioNode.connect(toNode.audioNode);
            fromNode.connections.push(id);

            connectionState.fromElement.classList.remove('active');
            connectionState = { fromId: null, fromElement: null };
            updateLines();
        }
    }

    function updateLines() {
        const svg = document.getElementById('connections');
        svg.innerHTML = ''; // Clear existing lines

        Object.keys(nodes).forEach(fromId => {
            const fromNode = nodes[fromId];
            if (!fromNode.connections) return;

            fromNode.connections.forEach(toId => {
                const toNode = nodes[toId];
                const outPort = fromNode.element.querySelector('.port.out');
                const inPort = toNode.element.querySelector('.port.in');

                if (outPort && inPort) {
                    const outRect = outPort.getBoundingClientRect();
                    const inRect = inPort.getBoundingClientRect();

                    const x1 = outRect.left + outRect.width / 2;
                    const y1 = outRect.top + outRect.height / 2 - 50; // offset for toolbar
                    const x2 = inRect.left + inRect.width / 2;
                    const y2 = inRect.top + inRect.height / 2 - 50;

                    const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                    const d = `M ${x1} ${y1} C ${x1 + 50} ${y1}, ${x2 - 50} ${y2}, ${x2} ${y2}`;
                    line.setAttribute('d', d);
                    line.setAttribute('stroke', '#4caf50');
                    line.setAttribute('stroke-width', '3');
                    line.setAttribute('fill', 'none');
                    svg.appendChild(line);
                }
            });
        });
    }

    // --- Recording / Export Logic ---
    function toggleRecording() {
        const btn = document.getElementById('recordBtn');
        if (!isRecording) {
            recordedChunks = [];
            mediaRecorder = new MediaRecorder(destStream.stream);
            mediaRecorder.ondataavailable = e => { if (e.data.size > 0) recordedChunks.push(e.data); };
            mediaRecorder.onstop = exportAudio;
            mediaRecorder.start();
            isRecording = true;
            btn.innerText = "Stop & Export";
            btn.style.background = "#ff0000";
        } else {
            mediaRecorder.stop();
            isRecording = false;
            btn.innerText = "Start Recording";
            btn.style.background = "#8b0000";
        }
    }

    function exportAudio() {
        const blob = new Blob(recordedChunks, { type: 'audio/webm' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = 'synth-export.webm';
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
    }

    // Initialize Master Output port listener
    document.querySelector('#master-out .port').addEventListener('click', (e) => {
        handlePortClick(e, e.target, 'master');
    });
</script>
</body>
</html>
```

### How to use this prototype:
1. **Add Modules:** Click "+ Oscillator" and "+ Lowpass Filter" in the top toolbar.
2. **Move Modules:** Click and drag the bold header of any module to organize your workspace.
3. **Connect Modules:** 
   * Click the output port (right side) of the Oscillator. It will turn green.
   * Click the input port (left side) of the Filter. A green wire will appear.
   * Click the output port of the Filter, then click the input port of the **Master Output**. You will now hear the sound.
4. **Tweak Sounds:** Adjust the sliders to change the Oscillator frequency and Filter cutoff in real-time.
5. **Export Audio:** Click "Start Recording", play with the sliders to create a dynamic sound, and click "Stop & Export". Your browser will automatically download a `.webm` audio file of your performance.

Here is a complete, executable prototype of an online dynamic sticker tool. It uses HTML5 Canvas for rendering and animation, and the `gif.js` library to export the result as a GIF. 

To ensure this runs smoothly as a single file, save the code below as an `.html` file (e.g., `sticker-tool.html`) and open it in your web browser. 

### Dynamic Sticker Tool Code (`index.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Dynamic Sticker Tool</title>
    <!-- Load gif.js for GIF generation -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.js"></script>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f4f4f9;
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }
        .toolbar {
            background: white;
            padding: 15px;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            margin-bottom: 20px;
            display: flex;
            gap: 15px;
            align-items: center;
            flex-wrap: wrap;
        }
        button, input[type="file"] {
            padding: 8px 12px;
            border: none;
            border-radius: 4px;
            background-color: #007bff;
            color: white;
            cursor: pointer;
            font-size: 14px;
        }
        button:hover { background-color: #0056b3; }
        button:disabled { background-color: #ccc; cursor: not-allowed; }
        canvas {
            background: #fff;
            box-shadow: 0 4px 6px rgba(0,0,0,0.1);
            border-radius: 8px;
            cursor: grab;
        }
        canvas:active { cursor: grabbing; }
        .instructions {
            margin-top: 10px;
            color: #666;
            font-size: 14px;
        }
    </style>
</head>
<body>

    <div class="toolbar">
        <div>
            <label for="bg-upload">1. Upload Background:</label>
            <input type="file" id="bg-upload" accept="image/*">
        </div>
        <div>
            <label>2. Add Sticker:</label>
            <button onclick="addSticker('😀', 'bounce')">Add Bouncing 😀</button>
            <button onclick="addSticker('⭐', 'rotate')">Add Rotating ⭐</button>
        </div>
        <div>
            <label>3. Export:</label>
            <button id="export-btn" onclick="exportGIF()">Download as GIF</button>
        </div>
    </div>

    <canvas id="canvas" width="600" height="400"></canvas>
    <div class="instructions">Drag stickers to move them. Animations are previewed in real-time.</div>

    <script>
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');

        let bgImage = null;
        let stickers = [];
        let isDragging = false;
        let draggedSticker = null;
        let animationFrameId;
        let globalTick = 0;

        // Handle Background Upload
        document.getElementById('bg-upload').addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = function(event) {
                const img = new Image();
                img.onload = function() {
                    bgImage = img;
                    // Resize canvas to fit image while maintaining aspect ratio (max width 600)
                    const scale = Math.min(600 / img.width, 400 / img.height);
                    canvas.width = img.width * scale;
                    canvas.height = img.height * scale;
                }
                img.src = event.target.result;
            }
            reader.readAsDataURL(file);
        });

        // Add a new sticker
        function addSticker(text, animType) {
            stickers.push({
                text: text,
                x: canvas.width / 2,
                y: canvas.height / 2,
                size: 50,
                animType: animType,
                tickOffset: Math.random() * 100
            });
        }

        // Mouse Events for Dragging
        canvas.addEventListener('mousedown', (e) => {
            const rect = canvas.getBoundingClientRect();
            const mouseX = e.clientX - rect.left;
            const mouseY = e.clientY - rect.top;

            // Check if clicked on a sticker (reverse order to pick top-most)
            for (let i = stickers.length - 1; i >= 0; i--) {
                const s = stickers[i];
                // Simple bounding box check
                if (mouseX >= s.x - s.size/2 && mouseX <= s.x + s.size/2 &&
                    mouseY >= s.y - s.size/2 && mouseY <= s.y + s.size/2) {
                    isDragging = true;
                    draggedSticker = s;
                    break;
                }
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            if (isDragging && draggedSticker) {
                const rect = canvas.getBoundingClientRect();
                draggedSticker.x = e.clientX - rect.left;
                draggedSticker.y = e.clientY - rect.top;
            }
        });

        canvas.addEventListener('mouseup', () => {
            isDragging = false;
            draggedSticker = null;
        });

        // Main Render Loop
        function render() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw Background
            if (bgImage) {
                ctx.drawImage(bgImage, 0, 0, canvas.width, canvas.height);
            } else {
                ctx.fillStyle = '#e9ecef';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = '#adb5bd';
                ctx.font = '20px Arial';
                ctx.textAlign = 'center';
                ctx.fillText('Please upload a background image', canvas.width/2, canvas.height/2);
            }

            // Draw Stickers
            stickers.forEach(s => {
                ctx.save();

                let currentY = s.y;
                let currentAngle = 0;

                // Calculate Animation states
                if (s.animType === 'bounce') {
                    currentY += Math.sin((globalTick + s.tickOffset) * 0.1) * 15;
                } else if (s.animType === 'rotate') {
                    currentAngle = (globalTick + s.tickOffset) * 0.05;
                }

                ctx.translate(s.x, currentY);
                ctx.rotate(currentAngle);

                ctx.font = `${s.size}px Arial`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(s.text, 0, 0);

                ctx.restore();
            });

            globalTick++;
            animationFrameId = requestAnimationFrame(render);
        }

        // Start the render loop
        render();

        // Export to GIF
        function exportGIF() {
            const btn = document.getElementById('export-btn');
            btn.innerText = "Rendering...";
            btn.disabled = true;

            // Note: gif.js requires a worker script. We use a public CDN for the worker.
            const gif = new GIF({
                workers: 2,
                quality: 10,
                workerScript: 'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
                width: canvas.width,
                height: canvas.height
            });

            // Capture 30 frames (approx 1 second of animation)
            const totalFrames = 30;
            let frameTick = globalTick;

            for (let i = 0; i < totalFrames; i++) {
                // Temporarily hijack the global tick to render specific frames
                globalTick = frameTick + i;

                // Force a synchronous render for the frame
                cancelAnimationFrame(animationFrameId);
                render(); 

                // Add the canvas state to the GIF
                gif.addFrame(canvas, {copy: true, delay: 33}); // ~30fps
            }

            // Restore normal animation loop
            globalTick = frameTick;
            render();

            gif.on('finished', function(blob) {
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'dynamic-sticker.gif';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);

                btn.innerText = "Download as GIF";
                btn.disabled = false;
            });

            gif.render();
        }
    </script>
</body>
</html>
```

### Features Included:
1. **Image Upload:** Users can upload any local image to serve as the background. The canvas automatically scales to fit the image.
2. **Dynamic Stickers:** Users can add text-based emojis that act as stickers. 
    * **Bounce Effect:** Uses a sine wave (`Math.sin`) to create a smooth up-and-down bouncing animation.
    * **Rotate Effect:** Continuously increments the rotation angle of the canvas context before drawing the sticker.
3. **Interactivity:** Users can click and drag the stickers around the canvas to position them perfectly.
4. **Real-time Preview:** The `requestAnimationFrame` loop ensures the user sees exactly what the final animation will look like.
5. **GIF Export:** Uses `gif.js` to capture 30 frames of the canvas animation, compile them into a GIF, and automatically trigger a download for the user.

*Note: Because `gif.js` utilizes Web Workers to encode the GIF, running this file directly via `file://` protocol might trigger CORS restrictions in some strict browsers (like Chrome). For the best experience, serve this HTML file using a local development server (e.g., VS Code Live Server, or `python -m http.server`).*

