        function addCircle() {
            const circle = new fabric.Circle({
                left: 150,
                top: 150,
                radius: 50,
                fill: 'transparent', // Transparent inside
                stroke: 'blue',      // Blue border
                strokeWidth: 3,
                cornerColor: 'red',
                cornerSize: 10,
                transparentCorners: false
            });
            canvas.add(circle);
            canvas.setActiveObject(circle);
        }

        // Function to add a Text annotation
        function addText() {
            const text = new fabric.IText('Double click to edit', {
                left: 200,
                top: 200,
                fontFamily: 'Arial',
                fill: '#000000',
                fontSize: 24,
                fontWeight: 'bold',
                backgroundColor: 'rgba(255, 255, 255, 0.7)' // Slight background to make text readable
            });
            canvas.add(text);
            canvas.setActiveObject(text);
        }

        // Function to delete the currently selected annotation
        function deleteSelected() {
            const activeObjects = canvas.getActiveObjects();
            if (activeObjects.length) {
                canvas.discardActiveObject();
                activeObjects.forEach(function(object) {
                    canvas.remove(object);
                });
            } else {
                alert('Please select an annotation to delete.');
            }
        }

        // Function to export the annotated image
        function exportImage() {
            // Deselect any active objects so selection borders don't show in export
            canvas.discardActiveObject();
            canvas.renderAll();

            // Get canvas data URL
            const dataURL = canvas.toDataURL({
                format: 'png',
                quality: 1
            });

            // Create a temporary link element to trigger the download
            const link = document.createElement('a');
            link.download = 'annotated-image.png';
            link.href = dataURL;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        // Add a default placeholder background so the canvas isn't completely empty initially
        window.onload = function() {
            const text = new fabric.Text('Please upload an image to start annotating', {
                left: canvas.width / 2,
                top: canvas.height / 2,
                originX: 'center',
                originY: 'center',
                fontSize: 20,
                fill: '#888',
                selectable: false
            });
            canvas.add(text);

            // Remove placeholder text when an image is uploaded
            imageLoader.addEventListener('change', function() {
                canvas.remove(text);
            });
        };
    </script>
</body>
</html>
