<body>

    <div class="controls-container">
        <h2 style="margin-top: 0; text-align: center;">Karaoke Sync Tool</h2>

        <div class="control-group">
            <label for="audio-upload">1. Upload Audio (MP3/WAV)</label>
            <input type="file" id="audio-upload" accept="audio/*">
        </div>

        <div class="control-group">
            <label for="lrc-upload">2. Upload Lyrics (.lrc)</label>
            <input type="file" id="lrc-upload" accept=".lrc">
        </div>

        <audio id="audio-player" controls></audio>

        <div class="toolbar">
            <div>
                <button class="btn-offset" onclick="adjustOffset(-0.5)">-0.5s</button>
                <span id="offset-display" style="margin: 0 10px;">Offset: 0.0s</span>
                <button class="btn-offset" onclick="adjustOffset(0.5)">+0.5s</button>
            </div>
            <button onclick="exportLRC()">Export LRC</button>
        </div>
    </div>

    <div id="lyrics-container">
        <div id="lyrics-content">
            <p class="lyric-line" style="color: #555;">Upload audio and LRC files to begin...</p>
        </div>
    </div>

    <script>
        let lyricsData = [];
        let currentOffset = 0; // in seconds
        let activeIndex = -1;

        const audioPlayer = document.getElementById('audio-player');
        const audioUpload = document.getElementById('audio-upload');
        const lrcUpload = document.getElementById('lrc-upload');
        const lyricsContent = document.getElementById('lyrics-content');
        const offsetDisplay = document.getElementById('offset-display');

        // Handle Audio Upload
        audioUpload.addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const url = URL.createObjectURL(file);
                audioPlayer.src = url;
            }
        });

        // Handle LRC Upload
        lrcUpload.addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    parseLRC(e.target.result);
                    renderLyrics();
                };
                reader.readAsText(file);
            }
        });

        // Parse LRC File
        function parseLRC(lrcText) {
            lyricsData = [];
            currentOffset = 0;
            updateOffsetDisplay();

            const lines = lrcText.split('\n');
            const timeRegEx = /\[(\d{2}):(\d{2}\.\d{2,3})\]/;

            lines.forEach(line => {
                const match = timeRegEx.exec(line);
                if (match) {
                    const minutes = parseInt(match[1], 10);
                    const seconds = parseFloat(match[2]);
                    const time = (minutes * 60) + seconds;
                    const text = line.replace(timeRegEx, '').trim();

                    if (text) {
                        lyricsData.push({ time, text });
                    }
                }
            });

            // Sort by time just in case
            lyricsData.sort((a, b) => a.time - b.time);
        }

        // Render Lyrics to DOM
        function renderLyrics() {
            lyricsContent.innerHTML = '';
            lyricsData.forEach((line, index) => {
                const p = document.createElement('p');
                p.className = 'lyric-line';
                p.innerText = line.text;
                p.id = `line-${index}`;

                // Click to seek
                p.addEventListener('click', () => {
                    audioPlayer.currentTime = line.time;
                    audioPlayer.play();
                });

                lyricsContent.appendChild(p);
            });
        }

        // Sync Lyrics with Audio
        audioPlayer.addEventListener('timeupdate', () => {
            if (lyricsData.length === 0) return;

            const currentTime = audioPlayer.currentTime;
            let newActiveIndex = -1;

            for (let i = 0; i < lyricsData.length; i++) {
                if (currentTime >= lyricsData[i].time) {
                    newActiveIndex = i;
                } else {
                    break;
                }
            }

            if (newActiveIndex !== activeIndex && newActiveIndex !== -1) {
                // Remove old active class
                if (activeIndex !== -1) {
                    const oldLine = document.getElementById(`line-${activeIndex}`);
                    if (oldLine) oldLine.classList.remove('active');
                }

                // Add new active class
                activeIndex = newActiveIndex;
                const newLine = document.getElementById(`line-${activeIndex}`);
                if (newLine) {
                    newLine.classList.add('active');
                    // Auto-scroll
                    newLine.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }
        });

        // Adjust Offset
        function adjustOffset(seconds) {
            if (lyricsData.length === 0) return;

            currentOffset += seconds;
            updateOffsetDisplay();

            lyricsData = lyricsData.map(line => {
                return {
                    ...line,
                    time: Math.max(0, line.time + seconds) // Prevent negative time
                };
            });

            // Force update highlight
            activeIndex = -1;
            audioPlayer.dispatchEvent(new Event('timeupdate'));
        }

        function updateOffsetDisplay() {
            offsetDisplay.innerText = `Offset: ${currentOffset > 0 ? '+' : ''}${currentOffset.toFixed(1)}s`;
        }

        // Export Modified LRC
        function exportLRC() {
            if (lyricsData.length === 0) {
                alert("No lyrics to export!");
                return;
            }

            let lrcOutput = "";
            lyricsData.forEach(line => {
                const minutes = Math.floor(line.time / 60);
                const seconds = (line.time % 60).toFixed(2);

                const minStr = minutes.toString().padStart(2, '0');
                const secStr = seconds.toString().padStart(5, '0'); // 00.00 format

                lrcOutput += `[${minStr}:${secStr}]${line.text}\n`;
            });

            const blob = new Blob([lrcOutput], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');
            a.href = url;
            a.download = 'synced_lyrics.lrc';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }
    </script>
</body>
</html>
```

### Features Included:
1. **Local File Processing:** Uses the HTML5 `FileReader` and `URL.createObjectURL` to process audio and text files entirely in the browser without uploading to a server.
2. **LRC Parsing:** Uses Regular Expressions to extract timestamps and text from standard `.lrc` files.
3. **Real-time Synchronization:** Listens to the `<audio>` element's `timeupdate` event to highlight the current line.
4. **Auto-Scrolling:** Automatically scrolls the lyrics container so the active lyric is always centered.
5. **Click-to-Seek:** Clicking on any lyric line will instantly jump the audio to that specific timestamp.
6. **Offset Adjustment:** Buttons to shift all timestamps forward or backward by 0.5 seconds to fix out-of-sync lyrics.
7. **Export:** Re-formats the adjusted timestamps back into standard `[mm:ss.xx]` LRC format and triggers a file download.

