                Perimeter: (2 * Math.PI * p.r).toFixed(2)
            }),
            formulas: "Area = π × r²\nPerimeter = 2 × π × r",
            draw: (svg, p) => {
                const cx = 150, cy = 150;
                const scale = Math.min(120 / p.r, 1); // Scale to fit
                const r = p.r * scale;
                svg.innerHTML = `
                    <circle cx="${cx}" cy="${cy}" r="${r}" fill="#bfdbfe" stroke="#2563eb" stroke-width="2"/>
                    <line x1="${cx}" y1="${cy}" x2="${cx + r}" y2="${cy}" stroke="#1e293b" stroke-width="2" stroke-dasharray="4"/>
