<body>
    <div id="ui">
        <div>SCORE: <span id="score">0</span></div>
        <div id="shieldBarContainer"><div id="shieldBar"></div></div>
    </div>
    <div id="gameOver">
        <div>GAME OVER</div>
        <button id="restartBtn" onclick="location.reload()">RESTART</button>
    </div>

    <!-- Include Three.js -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>

    <script>
        // --- Game State ---
        let score = 0;
        let shield = 100;
        let isGameOver = false;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.fog = new THREE.FogExp2(0x000000, 0.002);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0x404040);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.5);
        directionalLight.position.set(10, 20, 10);
        scene.add(directionalLight);

        // Dynamic explosion light
        const explosionLight = new THREE.PointLight(0xffaa00, 0, 50);
        scene.add(explosionLight);

        // --- Player (Spaceship) ---
        const playerGroup = new THREE.Group();

        // Ship body
        const bodyGeo = new THREE.ConeGeometry(1, 3, 8);
        bodyGeo.rotateX(Math.PI / 2);
        const bodyMat = new THREE.MeshPhongMaterial({ color: 0x00aaff, flatShading: true });
        const shipBody = new THREE.Mesh(bodyGeo, bodyMat);
        playerGroup.add(shipBody);

        // Ship wings
        const wingGeo = new THREE.BoxGeometry(4, 0.5, 1);
        const wingMat = new THREE.MeshPhongMaterial({ color: 0x0055aa, flatShading: true });
        const wings = new THREE.Mesh(wingGeo, wingMat);
        wings.position.z = 0.5;
        playerGroup.add(wings);

        // Shield effect
        const shieldGeo = new THREE.SphereGeometry(3, 16, 16);
        const shieldMat = new THREE.MeshPhongMaterial({ 
            color: 0x00ffff, 
            transparent: true, 
            opacity: 0.0,
            blending: THREE.AdditiveBlending
        });
        const shieldMesh = new THREE.Mesh(shieldGeo, shieldMat);
        playerGroup.add(shieldMesh);

        scene.add(playerGroup);

        // --- Stars Background ---
        const starsGeo = new THREE.BufferGeometry();
        const starsCount = 1000;
        const posArray = new Float32Array(starsCount * 3);
        for(let i = 0; i < starsCount * 3; i++) {
            posArray[i] = (Math.random() - 0.5) * 200;
        }
        starsGeo.setAttribute('position', new THREE.BufferAttribute(posArray, 3));
        const starsMat = new THREE.PointsMaterial({ size: 0.5, color: 0xffffff });
        const starsMesh = new THREE.Points(starsGeo, starsMat);
        starsMesh.position.y = -10;
        scene.add(starsMesh);

        // --- Input Handling ---
        const keys = { w: false, a: false, s: false, d: false };
        const mouse = new THREE.Vector2();
        const raycaster = new THREE.Raycaster();
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); // Y=0 plane for mouse intersection

        window.addEventListener('keydown', (e) => {
            if(keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = true;
        });
        window.addEventListener('keyup', (e) => {
            if(keys.hasOwnProperty(e.key.toLowerCase())) keys[e.key.toLowerCase()] = false;
        });
        window.addEventListener('mousemove', (e) => {
            mouse.x = (e.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;
        });
        window.addEventListener('mousedown', (e) => {
            if(e.button === 0 && !isGameOver) shoot();
        });
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // --- Game Entities ---
        const bullets = [];
        const asteroids = [];
        const particles = [];

        function shoot() {
            const bulletGeo = new THREE.SphereGeometry(0.3, 8, 8);
            const bulletMat = new THREE.MeshBasicMaterial({ color: 0xffff00 });
            const bullet = new THREE.Mesh(bulletGeo, bulletMat);

            bullet.position.copy(playerGroup.position);

            // Calculate direction based on ship rotation
            const direction = new THREE.Vector3(0, 0, -1);
            direction.applyQuaternion(playerGroup.quaternion);

            scene.add(bullet);
            bullets.push({ mesh: bullet, velocity: direction.multiplyScalar(1.5), life: 100 });
        }

        function spawnAsteroid() {
            const size = Math.random() * 2 + 1;
            const astGeo = new THREE.DodecahedronGeometry(size);
            const astMat = new THREE.MeshPhongMaterial({ color: 0x888888, flatShading: true });
            const asteroid = new THREE.Mesh(astGeo, astMat);

            // Spawn in a circle around the center
            const angle = Math.random() * Math.PI * 2;
            const radius = 60;
            asteroid.position.set(Math.cos(angle) * radius, 0, Math.sin(angle) * radius);

            // Move towards a random point near the player
            const target = new THREE.Vector3(
                playerGroup.position.x + (Math.random() - 0.5) * 20,
                0,
                playerGroup.position.z + (Math.random() - 0.5) * 20
            );

            const velocity = new THREE.Vector3().subVectors(target, asteroid.position).normalize().multiplyScalar(Math.random() * 0.2 + 0.1);
            const rotationSpeed = new THREE.Vector3(Math.random() * 0.05, Math.random() * 0.05, Math.random() * 0.05);

            scene.add(asteroid);
            asteroids.push({ mesh: asteroid, velocity, rotationSpeed, size });
        }

        function createExplosion(position, color) {
            const particleCount = 15;
            const pGeo = new THREE.BoxGeometry(0.5, 0.5, 0.5);
            const pMat = new THREE.MeshPhongMaterial({ color: color, flatShading: true });

            for(let i = 0; i < particleCount; i++) {
                const particle = new THREE.Mesh(pGeo, pMat);
                particle.position.copy(position);

                const velocity = new THREE.Vector3(
                    (Math.random() - 0.5) * 1,
                    (Math.random() - 0.5) * 1,
                    (Math.random() - 0.5) * 1
                );

                scene.add(particle);
                particles.push({ mesh: particle, velocity, life: 30 });
            }

            // Dynamic light flash
            explosionLight.position.copy(position);
            explosionLight.intensity = 2;
            explosionLight.color.setHex(color);
        }

        // --- Main Game Loop ---
        const clock = new THREE.Clock();
        let spawnTimer = 0;

        function animate() {
            requestAnimationFrame(animate);

            if (isGameOver) return;

            const delta = clock.getDelta();

            // Player Movement
            const speed = 0.5;
            if (keys.w) playerGroup.position.z -= speed;
            if (keys.s) playerGroup.position.z += speed;
            if (keys.a) playerGroup.position.x -= speed;
            if (keys.d) playerGroup.position.x += speed;

            // Keep player in bounds
            playerGroup.position.x = Math.max(-40, Math.min(40, playerGroup.position.x));
            playerGroup.position.z = Math.max(-30, Math.min(30, playerGroup.position.z));

            // Player Rotation (Aim at mouse)
            raycaster.setFromCamera(mouse, camera);
            const intersect = new THREE.Vector3();
            raycaster.ray.intersectPlane(plane, intersect);
            if (intersect) {
                playerGroup.lookAt(intersect.x, 0, intersect.z);
            }

            // Camera Follow
            camera.position.x += (playerGroup.position.x - camera.position.x) * 0.1;
            camera.position.z += (playerGroup.position.z + 30 - camera.position.z) * 0.1;
            camera.position.y = 40;
            camera.lookAt(camera.position.x, 0, camera.position.z - 20);

            // Shield Effect Fade
            if (shieldMesh.material.opacity > 0) {
                shieldMesh.material.opacity -= 0.02;
            }

            // Explosion Light Fade
            if (explosionLight.intensity > 0) {
                explosionLight.intensity -= 0.1;
            }

            // Update Bullets
            for (let i = bullets.length - 1; i >= 0; i--) {
                const b = bullets[i];
                b.mesh.position.add(b.velocity);
                b.life--;
                if (b.life <= 0) {
                    scene.remove(b.mesh);
                    bullets.splice(i, 1);
                }
            }

            // Spawn Asteroids
            spawnTimer += delta;
            if (spawnTimer > 1.0) {
                spawnAsteroid();
                spawnTimer = 0;
            }

            // Update Asteroids & Collisions
            for (let i = asteroids.length - 1; i >= 0; i--) {
                const a = asteroids[i];
                a.mesh.position.add(a.velocity);
                a.mesh.rotation.x += a.rotationSpeed.x;
                a.mesh.rotation.y += a.rotationSpeed.y;
                a.mesh.rotation.z += a.rotationSpeed.z;

                // Out of bounds
                if (a.mesh.position.length() > 100) {
                    scene.remove(a.mesh);
                    asteroids.splice(i, 1);
                    continue;
                }

                // Collision with Player
                if (a.mesh.position.distanceTo(playerGroup.position) < a.size + 2) {
                    shield -= 20;
                    shieldMesh.material.opacity = 0.8; // Shield impact effect
                    document.getElementById('shieldBar').style.width = Math.max(0, shield) + '%';

                    if (shield <= 20) document.getElementById('shieldBar').style.backgroundColor = '#f00';

                    createExplosion(a.mesh.position, 0x00ffff);
                    scene.remove(a.mesh);
                    asteroids.splice(i, 1);

                    if (shield <= 0) {
                        isGameOver = true;
                        document.getElementById('gameOver').style.display = 'block';
                        createExplosion(playerGroup.position, 0xff0000);
                        scene.remove(playerGroup);
                    }
                    continue;
                }

                // Collision with Bullets
                for (let j = bullets.length - 1; j >= 0; j--) {
                    const b = bullets[j];
                    if (a.mesh.position.distanceTo(b.mesh.position) < a.size + 0.5) {
                        // Destroy Asteroid
                        createExplosion(a.mesh.position, 0xffaa00);
                        scene.remove(a.mesh);
                        asteroids.splice(i, 1);

                        // Destroy Bullet
                        scene.remove(b.mesh);
                        bullets.splice(j, 1);

                        // Update Score
                        score += Math.floor(10 * a.size);
                        document.getElementById('score').innerText = score;
                        break;
                    }
                }
            }

            // Update Particles
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.mesh.position.add(p.velocity);
                p.mesh.scale.multiplyScalar(0.9);
                p.life--;
                if (p.life <= 0) {
                    scene.remove(p.mesh);
                    particles.splice(i, 1);
                }
            }

            renderer.render(scene, camera);
        }

        // Start Game
        animate();
    </script>
</body>
</html>
```

Here is a complete, executable solution using vanilla JavaScript. It runs in the browser, utilizes the Web `Notification` API for system notifications, and uses `new Function()` to execute custom JavaScript snippets safely within its scope.

### Security Warning
Executing custom JavaScript code from strings (using `eval` or `new Function`) can be a security risk (Cross-Site Scripting or XSS) if the code snippets are provided by untrusted users. Ensure that only authorized users can create or modify these tasks.

### Implementation (HTML + JavaScript)

Save the following code as an `.html` file (e.g., `scheduler.html`) and open it in any modern web browser. 

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Task Scheduler</title>
    <style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        .log { background: #f4f4f4; padding: 10px; border: 1px solid #ddd; height: 300px; overflow-y: auto; }
    </style>
</head>
<body>
    <h1>Browser Task Scheduler</h1>
    <p>Please allow notification permissions when prompted.</p>
    <button onclick="scheduler.start()">Start Scheduler</button>
    <button onclick="scheduler.stop()">Stop Scheduler</button>

    <h3>Execution Log:</h3>
    <div class="log" id="log"></div>

    <script>
        class TaskScheduler {
            constructor() {
                this.tasks = [];
                this.intervalId = null;
                this.requestNotificationPermission();
            }

            // Request system notification permission
            async requestNotificationPermission() {
                if (!("Notification" in window)) {
                    this.log("This browser does not support desktop notification");
                } else if (Notification.permission !== "denied" && Notification.permission !== "granted") {
                    await Notification.requestPermission();
                }
            }

            /**
             * Add a new task
             * @param {string} name - Task name
             * @param {Object} schedule - { hour: Number (optional), minute: Number }
             * @param {string} notificationText - Text to display in the notification
             * @param {string} codeSnippet - JS code to execute
             */
            addTask(name, schedule, notificationText, codeSnippet) {
                this.tasks.push({
                    name,
                    schedule,
                    notificationText,
                    codeSnippet,
                    lastRun: null // Prevent multiple executions in the same minute
                });
                this.log(`Task added: ${name}`);
            }

            start() {
                if (this.intervalId) return;
                this.log("Scheduler started. Checking tasks every minute...");

                // Check immediately, then every 60 seconds
                this.checkTasks();
                this.intervalId = setInterval(() => this.checkTasks(), 60000);
            }

            stop() {
                if (this.intervalId) {
                    clearInterval(this.intervalId);
                    this.intervalId = null;
                    this.log("Scheduler stopped.");
                }
            }

            checkTasks() {
                const now = new Date();
                const currentHour = now.getHours();
                const currentMinute = now.getMinutes();
                const dateString = now.toDateString();

                this.tasks.forEach(task => {
                    const { schedule } = task;
                    let isDue = false;

                    // Check if it's an hourly task (only minute is specified)
                    if (schedule.hour === undefined && schedule.minute === currentMinute) {
                        isDue = true;
                    } 
                    // Check if it's a daily task (both hour and minute specified)
                    else if (schedule.hour === currentHour && schedule.minute === currentMinute) {
                        isDue = true;
                    }

                    // Ensure it only runs once per scheduled minute
                    const runKey = `${dateString}-${currentHour}-${currentMinute}`;
                    if (isDue && task.lastRun !== runKey) {
                        task.lastRun = runKey;
                        this.executeTask(task);
                    }
                });
            }

            executeTask(task) {
                this.log(`Executing task: ${task.name}`);

                // 1. Show System Notification
                if (Notification.permission === "granted") {
                    new Notification(task.name, {
                        body: task.notificationText,
                        icon: "https://cdn-icons-png.flaticon.com/512/825/825590.png" // Placeholder icon
                    });
                }

                // 2. Execute Custom JS Code Snippet
                if (task.codeSnippet) {
                    try {
                        // Using new Function creates a safe execution scope compared to eval()
                        const executeCode = new Function(task.codeSnippet);
                        executeCode();
                        this.log(`Code executed successfully for: ${task.name}`);
                    } catch (error) {
                        this.log(`Error executing code for ${task.name}: ${error.message}`);
                        console.error(error);
                    }
                }
            }

            log(message) {
                const logDiv = document.getElementById('log');
                const time = new Date().toLocaleTimeString();
                logDiv.innerHTML += `<div>[${time}] ${message}</div>`;
                logDiv.scrollTop = logDiv.scrollHeight;
            }
        }

        // --- Initialization and Usage ---
        const scheduler = new TaskScheduler();

        // Example 1: Daily 9:00 AM Reminder
        scheduler.addTask(
            "Morning Standup",
            { hour: 9, minute: 0 },
            "Time for the daily 9:00 AM standup meeting!",
            "console.log('Standup time!');"
        );

        // Example 2: Hourly Time Announcement (Runs at minute 0 of every hour)
        scheduler.addTask(
            "Hourly Chime",
            { minute: 0 },
            "Another hour has passed.",
            "console.log('Hourly chime executed.');"
        );

        // Example 3: Dynamic Test Task (Runs 1 minute from now to test functionality)
        const testTime = new Date(Date.now() + 60000);
        scheduler.addTask(
            "Test Task",
            { hour: testTime.getHours(), minute: testTime.getMinutes() },
            "This is a test notification!",
            "alert('Custom JS Executed: Test Task Complete!');"
        );

        // Note: To test location.reload(), you can add a task like this:
        /*
        scheduler.addTask(
            "Page Reload",
            { hour: 12, minute: 0 },
            "Reloading the page...",
            "location.reload();"
        );
        */
    </script>
</body>
</html>
```

### How it works:
1. **Permissions:** When the page loads, it immediately asks the user for permission to display system notifications.
2. **Task Definition:** Tasks are defined with a `schedule` object. If `hour` is omitted, it acts as an hourly task (triggering whenever the clock hits that specific minute). If both `hour` and `minute` are provided, it acts as a daily task.
3. **Execution Loop:** The `start()` method sets up a `setInterval` that checks the current time against the scheduled tasks every 60 seconds.
4. **Idempotency:** The `lastRun` property ensures that if the interval fires twice within the same minute, the task is only executed once.
5. **Code Execution:** The `new Function(codeSnippet)` constructor is used to parse and execute the string as JavaScript. This is generally safer and faster than `eval()`.

