        function runProofEngine() {
            derivedSteps = [];
            let currentFacts = [...knownFacts];
            let addedNew = true;

            // Simple rules for demonstration
            while (addedNew) {
                addedNew = false;
                const newFacts = [];

                for (let i = 0; i < currentFacts.length; i++) {
                    for (let j = i + 1; j < currentFacts.length; j++) {
                        const f1 = currentFacts[i];
                        const f2 = currentFacts[j];

                        // Rule 1: Transitivity of equal sides (If A=B and B=C, then A=C)
                        if (f1.type === 'equal_sides' && f2.type === 'equal_sides') {
                            let derived = null;
                            if (f1.e2 === f2.e1 && f1.e1 !== f2.e2) derived = { e1: f1.e1, e2: f2.e2 };
                            else if (f1.e2 === f2.e2 && f1.e1 !== f2.e1) derived = { e1: f1.e1, e2: f2.e1 };
                            else if (f1.e1 === f2.e1 && f1.e2 !== f2.e2) derived = { e1: f1.e2, e2: f2.e2 };
                            else if (f1.e1 === f2.e2 && f1.e2 !== f2.e1) derived = { e1: f1.e2, e2: f2.e1 };

                            if (derived) {
                                // Check if already exists
                                const exists = currentFacts.some(f => f.type === 'equal_sides' && 
                                    ((f.e1 === derived.e1 && f.e2 === derived.e2) || (f.e1 === derived.e2 && f.e2 === derived.e1)));

                                if (!exists) {
                                    const newFact = {
                                        type: 'equal_sides',
                                        e1: derived.e1,
                                        e2: derived.e2,
                                        isGiven: false,
                                        reason: `Transitive property from ${f1.e1}=${f1.e2} and ${f2.e1}=${f2.e2}`
                                    };
                                    newFacts.push(newFact);
                                    derivedSteps.push(newFact);
                                    addedNew = true;
                                }
                            }
                        }

                        // Rule 2: Parallel lines imply alternate interior angles (Simplified mock logic)
                        // If AB || CD, mock derive that angle ABC = BCD
                        if (f1.type === 'parallel') {
                            const ang1 = f1.e1[1] + f1.e1[0] + f1.e2[0]; // Mock angle generation
                            const ang2 = f1.e1[0] + f1.e2[0] + f1.e2[1];

                            const exists = currentFacts.some(f => f.type === 'equal_angles' && f.e1 === ang1 && f.e2 === ang2);
                            if (!exists && !newFacts.some(f => f.type === 'equal_angles' && f.e1 === ang1)) {
                                const newFact = {
                                    type: 'equal_angles',
                                    e1: ang1,
                                    e2: ang2,
                                    isGiven: false,
                                    reason: `Alternate interior angles of parallel lines ${f1.e1} || ${f1.e2}`
                                };
                                newFacts.push(newFact);
                                derivedSteps.push(newFact);
                                addedNew = true;
                            }
                        }
                    }
                }
                currentFacts = currentFacts.concat(newFacts);
            }

            renderProofTree();
        }

        function renderProofTree() {
            const treeContainer = document.getElementById('proofTree');
            treeContainer.innerHTML = '';

            if (derivedSteps.length === 0) {
                treeContainer.innerHTML = '<p style="color: #7f8c8d; font-size: 0.9rem;">No new steps derived yet. Add more conditions.</p>';
                return;
            }

            derivedSteps.forEach((step, index) => {
                const stepDiv = document.createElement('div');
                stepDiv.className = 'proof-step';

                let titleText = '';
                if (step.type === 'equal_sides') titleText = `Step ${index + 1}: ${step.e1} = ${step.e2}`;
                if (step.type === 'equal_angles') titleText = `Step ${index + 1}: ∠${step.e1} = ∠${step.e2}`;

                stepDiv.innerHTML = `
                    <div class="proof-step-title">${titleText}</div>
                    <div class="proof-step-reason"><strong>Reason:</strong> ${step.reason}</div>
