                // Toggle explanation on click
                stepDiv.addEventListener('click', () => {
                    stepDiv.classList.toggle('active');
                });

                treeContainer.appendChild(stepDiv);
            });
        }

        document.getElementById('verifyBtn').addEventListener('click', () => {
            if (derivedSteps.length > 0) {
                alert(`Verification Complete! The system successfully derived ${derivedSteps.length} logical steps from the given conditions.`);
            } else {
                alert("Verification Failed. Not enough conditions to derive a proof. Please add more known facts.");
            }
        });

        // Initialize empty canvas
        drawGeometry();
    </script>
