    const urlInput = document.getElementById('urlInput');
    const generateBtn = document.getElementById('generateBtn');
    const loader = document.getElementById('loader');
    const resultArea = document.getElementById('resultArea');
    const screenshotImg = document.getElementById('screenshotImg');
    const downloadBtn = document.getElementById('downloadBtn');
    const errorMsg = document.getElementById('errorMsg');

    // Function to validate URL
    function isValidUrl(string) {
        try {
            new URL(string);
            return true;
        } catch (_) {
            return false;  
        }
    }

    generateBtn.addEventListener('click', () => {
        let url = urlInput.value.trim();

        // Auto-prepend https:// if missing
        if (url && !url.startsWith('http://') && !url.startsWith('https://')) {
            url = 'https://' + url;
            urlInput.value = url;
        }

        if (!isValidUrl(url)) {
            errorMsg.style.display = 'block';
            return;
        }

        errorMsg.style.display = 'none';
        resultArea.style.display = 'none';
        loader.style.display = 'block';
        generateBtn.disabled = true;

        // Using thum.io free API for generating screenshots
        // width/800 sets the viewport width, crop/800 crops the height
        const apiUrl = `https://image.thum.io/get/width/800/crop/800/${url}`;

        // Set image source
        screenshotImg.src = apiUrl;

        // Handle image load
        screenshotImg.onload = () => {
            loader.style.display = 'none';
            resultArea.style.display = 'flex';
            generateBtn.disabled = false;
        };

        // Handle image error
        screenshotImg.onerror = () => {
            loader.style.display = 'none';
            errorMsg.textContent = "Failed to generate screenshot. The website might be blocking access.";
            errorMsg.style.display = 'block';
            generateBtn.disabled = false;
        };
    });

    // Handle Download
    downloadBtn.addEventListener('click', async () => {
        try {
            // Fetch the image as a blob to force download instead of opening in a new tab
            const response = await fetch(screenshotImg.src);
            const blob = await response.blob();
            const blobUrl = window.URL.createObjectURL(blob);

            const a = document.createElement('a');
            a.href = blobUrl;
            // Extract domain name for the filename
            const domain = new URL(urlInput.value).hostname;
            a.download = `screenshot-${domain}.png`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(blobUrl);
        } catch (error) {
            // Fallback if CORS blocks the fetch request
            window.open(screenshotImg.src, '_blank');
        }
    });

    // Allow pressing "Enter" to trigger generation
    urlInput.addEventListener('keypress', function (e) {
        if (e.key === 'Enter') {
            generateBtn.click();
        }
    });
</script>

</body>
</html>
```

### How it works:
1. **UI & Styling:** Uses modern CSS variables and flexbox to create a clean, responsive card layout.
2. **URL Validation:** The JavaScript checks if the input is a valid URL and automatically prepends `https://` if the user forgets it.
3. **Screenshot Generation:** It utilizes the `image.thum.io` API. By passing the target URL to this API, the service spins up a headless browser, takes the screenshot, and returns the image directly.
4. **Download Logic:** The download button uses the `fetch` API to grab the image as a `Blob`. It then creates a temporary object URL and an invisible `<a>` tag with the `download` attribute to force the browser to save the file locally (naming it based on the target domain). If CORS prevents the blob fetch, it gracefully falls back to opening the image in a new tab.

