<body>

    <div class="main-content">
        <!-- crossorigin="anonymous" is required to allow canvas to capture frames from external URLs -->
        <video id="videoPlayer" controls crossorigin="anonymous">
            <source src="https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4" type="video/mp4">
            Your browser does not support the video tag.
        </video>

        <div class="timeline-container" id="timelineContainer">
            <div class="timeline-progress" id="timelineProgress"></div>
            <div id="markersContainer"></div>
        </div>

        <div class="controls">
            <input type="text" id="noteInput" placeholder="Enter a note for this bookmark...">
            <button onclick="addBookmark()">Add Bookmark</button>
            <button class="file-btn" onclick="exportProject()">Export JSON</button>
            <button class="file-btn" onclick="document.getElementById('importFile').click()">Import JSON</button>
            <input type="file" id="importFile" accept=".json" style="display: none;" onchange="importProject(event)">
        </div>
    </div>

    <div class="sidebar">
        <h2>Bookmarks</h2>
        <div id="bookmarkList"></div>
    </div>

    <!-- Hidden canvas for thumbnail generation -->
    <canvas id="thumbCanvas" style="display: none;"></canvas>

    <script>
        const video = document.getElementById('videoPlayer');
        const timelineContainer = document.getElementById('timelineContainer');
        const timelineProgress = document.getElementById('timelineProgress');
        const markersContainer = document.getElementById('markersContainer');
        const bookmarkList = document.getElementById('bookmarkList');
        const noteInput = document.getElementById('noteInput');
        const canvas = document.getElementById('thumbCanvas');
        const ctx = canvas.getContext('2d');

        let bookmarks = [];

        // Update timeline progress bar
        video.addEventListener('timeupdate', () => {
            if (video.duration) {
                const percent = (video.currentTime / video.duration) * 100;
                timelineProgress.style.width = `${percent}%`;
            }
        });

        // Click on timeline to seek
        timelineContainer.addEventListener('click', (e) => {
            if (e.target.classList.contains('marker')) return; // Let marker handle its own click
            const rect = timelineContainer.getBoundingClientRect();
            const pos = (e.clientX - rect.left) / rect.width;
            video.currentTime = pos * video.duration;
        });

        function formatTime(seconds) {
            const m = Math.floor(seconds / 60).toString().padStart(2, '0');
            const s = Math.floor(seconds % 60).toString().padStart(2, '0');
            return `${m}:${s}`;
        }

        function generateThumbnail() {
            // Set canvas dimensions to match video aspect ratio (scaled down)
            canvas.width = 160;
            canvas.height = 90;
            try {
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                return canvas.toDataURL('image/jpeg', 0.7);
            } catch (e) {
                console.warn("Canvas tainted by cross-origin data. Thumbnail generation failed.");
                return ""; // Fallback if CORS prevents image capture
            }
        }

        function addBookmark() {
            if (!video.duration) return alert("Please wait for the video to load.");

            const time = video.currentTime;
            const note = noteInput.value.trim() || "Bookmark";
            const thumbnail = generateThumbnail();

            const bookmark = {
                id: Date.now().toString(),
                time: time,
                note: note,
                thumbnail: thumbnail
            };

            bookmarks.push(bookmark);
            bookmarks.sort((a, b) => a.time - b.time); // Keep sorted by time

            noteInput.value = ''; // Clear input
            renderBookmarks();
        }

        function deleteBookmark(id, event) {
            event.stopPropagation(); // Prevent triggering the jump-to-time click
            bookmarks = bookmarks.filter(b => b.id !== id);
            renderBookmarks();
        }

        function jumpToTime(time) {
            video.currentTime = time;
            video.play();
        }

        function renderBookmarks() {
            // Clear current UI
            markersContainer.innerHTML = '';
            bookmarkList.innerHTML = '';

            bookmarks.forEach(bookmark => {
                // 1. Render Timeline Marker
                const percent = (bookmark.time / video.duration) * 100;
                const marker = document.createElement('div');
                marker.className = 'marker';
                marker.style.left = `${percent}%`;
                marker.setAttribute('data-note', bookmark.note);
                marker.onclick = () => jumpToTime(bookmark.time);
                markersContainer.appendChild(marker);

                // 2. Render Sidebar List Item
                const item = document.createElement('div');
                item.className = 'bookmark-item';
                item.onclick = () => jumpToTime(bookmark.time);

                item.innerHTML = `
                    <img src="${bookmark.thumbnail}" class="bookmark-thumb" alt="Thumb">
                    <div class="bookmark-info">
                        <span class="bookmark-time">${formatTime(bookmark.time)}</span>
                        <span class="bookmark-note">${bookmark.note}</span>
                    </div>
                    <button class="delete-btn" onclick="deleteBookmark('${bookmark.id}', event)">X</button>
                `;
                bookmarkList.appendChild(item);
            });
        }

        // Export to JSON
        function exportProject() {
            const dataStr = JSON.stringify(bookmarks, null, 2);
            const blob = new Blob([dataStr], { type: "application/json" });
            const url = URL.createObjectURL(blob);

            const a = document.createElement('a');
            a.href = url;
            a.download = 'video-bookmarks.json';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }

        // Import from JSON
        function importProject(event) {
            const file = event.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = function(e) {
                try {
                    const importedData = JSON.parse(e.target.result);
                    if (Array.isArray(importedData)) {
                        bookmarks = importedData;
                        renderBookmarks();
                        alert("Project imported successfully!");
                    } else {
                        alert("Invalid file format.");
                    }
                } catch (err) {
                    alert("Error parsing JSON file.");
                }
            };
            reader.readAsText(file);
            event.target.value = ''; // Reset file input
        }

        // Initial render on video load
        video.addEventListener('loadedmetadata', renderBookmarks);
    </script>
</body>
</html>
```

### Features Included:
1. **Video Player & Timeline**: Uses a standard HTML5 video player. A custom timeline bar tracks the video progress.
2. **Add Bookmarks**: Pausing/Playing the video and clicking "Add Bookmark" captures the exact timestamp.
3. **Thumbnail Generation**: Uses a hidden HTML5 `<canvas>` to capture the current video frame and converts it to a Base64 image string to attach to the bookmark. *(Note: The video tag includes `crossorigin="anonymous"` to prevent CORS tainting when capturing frames from external URLs).*
4. **Visual Markers**: Red markers appear on the timeline. Hovering over them displays the text note. Clicking them jumps the video to that exact timestamp.
5. **Sidebar Navigation**: A list on the right displays the thumbnail, timestamp, and note. Clicking any item jumps to that part of the video. You can also delete bookmarks from here.
6. **Export/Import**: 
   - **Export**: Serializes the bookmark array (including Base64 thumbnails, times, and notes) into a `.json` file and triggers a download.
   - **Import**: Reads a previously exported `.json` file and restores all markers and thumbnails to the timeline.

