    const ctx = exportCanvas.getContext('2d');

    let subtitles = [];
    let activeSubtitle = null;

    // Handle Video Upload
    videoUpload.addEventListener('change', function(e) {
        const file = e.target.files[0];
        if (file) {
            const url = URL.createObjectURL(file);
            videoPlayer.src = url;
            exportBtn.disabled = false;
        }
    });

    // Add Subtitle to Array and UI
    addSubtitleBtn.addEventListener('click', () => {
        const start = parseFloat(document.getElementById('subStart').value);
        const end = parseFloat(document.getElementById('subEnd').value);
        const text = document.getElementById('subText').value;
        const size = document.getElementById('subSize').value;
        const color = document.getElementById('subColor').value;
        const font = document.getElementById('subFont').value;

        if (!text || start >= end) {
            alert("Please enter valid text and ensure End Time is greater than Start Time.");
            return;
        }

        const sub = { start, end, text, size, color, font };
        subtitles.push(sub);

        // Sort subtitles by start time
        subtitles.sort((a, b) => a.start - b.start);
        renderSubtitleList();
        document.getElementById('subText').value = ''; // clear input
    });

    function renderSubtitleList() {
        subtitleList.innerHTML = '';
        subtitles.forEach((sub, index) => {
            const div = document.createElement('div');
            div.className = 'subtitle-item';
            div.innerHTML = `<strong>${sub.start}s - ${sub.end}s:</strong> ${sub.text} <br>
                             <small>Font: ${sub.font}, Size: ${sub.size}px, Color: <span style="color:${sub.color}">&#9608;</span></small>`;
            subtitleList.appendChild(div);
        });
    }

    // Sync Subtitles during playback
    videoPlayer.addEventListener('timeupdate', () => {
        const currentTime = videoPlayer.currentTime;
        activeSubtitle = subtitles.find(sub => currentTime >= sub.start && currentTime <= sub.end);

        if (activeSubtitle) {
            subtitleOverlay.innerText = activeSubtitle.text;
            subtitleOverlay.style.fontSize = activeSubtitle.size + 'px';
            subtitleOverlay.style.color = activeSubtitle.color;
            subtitleOverlay.style.fontFamily = activeSubtitle.font;
        } else {
            subtitleOverlay.innerText = '';
        }
    });

    // Export Logic using Canvas and MediaRecorder
    exportBtn.addEventListener('click', async () => {
        if (!videoPlayer.src) return;

        exportBtn.disabled = true;
        exportStatus.innerText = "Preparing export... Please wait.";

        // Set canvas dimensions to match video
        exportCanvas.width = videoPlayer.videoWidth;
        exportCanvas.height = videoPlayer.videoHeight;

        // Setup MediaStream from Canvas
        const canvasStream = exportCanvas.captureStream(30); // 30 FPS

        // Attempt to capture audio from the original video
        let audioStream;
        if (videoPlayer.captureStream) {
            audioStream = videoPlayer.captureStream();
        } else if (videoPlayer.mozCaptureStream) {
            audioStream = videoPlayer.mozCaptureStream();
        }

        if (audioStream && audioStream.getAudioTracks().length > 0) {
            canvasStream.addTrack(audioStream.getAudioTracks()[0]);
        }

        const mediaRecorder = new MediaRecorder(canvasStream, { mimeType: 'video/webm; codecs=vp9' });
        const recordedChunks = [];

        mediaRecorder.ondataavailable = e => {
            if (e.data.size > 0) recordedChunks.push(e.data);
        };

        mediaRecorder.onstop = () => {
            const blob = new Blob(recordedChunks, { type: 'video/webm' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'video_with_subtitles.webm';
            a.click();

            exportBtn.disabled = false;
            exportStatus.innerText = "Export complete!";
            videoPlayer.controls = true;
        };

        // Start recording process
        videoPlayer.currentTime = 0;
        videoPlayer.controls = false; // Hide controls during recording

        videoPlayer.onseeked = () => {
            mediaRecorder.start();
            videoPlayer.play();
            exportStatus.innerText = "Recording in progress... Do not switch tabs.";
            drawFrame();
        };
    });

    function drawFrame() {
        if (videoPlayer.paused || videoPlayer.ended) {
            if (videoPlayer.ended && mediaRecorder.state === 'recording') {
                mediaRecorder.stop();
            }
            return;
        }

        // Draw Video Frame
        ctx.drawImage(videoPlayer, 0, 0, exportCanvas.width, exportCanvas.height);

        // Draw Subtitle if active
        if (activeSubtitle) {
            ctx.textAlign = "center";
            ctx.textBaseline = "bottom";

            // Scale font size relative to video resolution vs screen resolution
            const scaleFactor = exportCanvas.width / videoPlayer.clientWidth;
            const scaledFontSize = activeSubtitle.size * scaleFactor;

            ctx.font = `bold ${scaledFontSize}px ${activeSubtitle.font}`;

            const x = exportCanvas.width / 2;
            const y = exportCanvas.height - (exportCanvas.height * 0.1); // 10% from bottom

            // Draw text shadow/stroke for readability
            ctx.fillStyle = "black";
            ctx.fillText(activeSubtitle.text, x + 2, y + 2);

            // Draw actual text
            ctx.fillStyle = activeSubtitle.color;
            ctx.fillText(activeSubtitle.text, x, y);
        }

        requestAnimationFrame(drawFrame);
    }
</script>
</body>
</html>
