function Cart({ cart, setCart }) {
  const activeItems = cart.filter(item => item.status !== 'paid');

  const handleNegotiate = (productId, proposedPrice) => {
    setCart(cart.map(item => {
      if (item.product.id === productId) {
        return { ...item, status: 'pending', proposedPrice: Number(proposedPrice) };
      }
      return item;
    }));

    // Simulate seller response after 2 seconds
    setTimeout(() => {
      setCart(currentCart => currentCart.map(item => {
        if (item.product.id === productId && item.status === 'pending') {
          // Mock logic: Seller accepts if proposed price is >= 80% of original price
          const isAccepted = item.proposedPrice >= (item.product.price * 0.8);
          return { 
            ...item, 
            status: isAccepted ? 'agreed' : 'rejected',
            finalPrice: isAccepted ? item.proposedPrice : item.product.price
          };
        }
        return item;
      }));
    }, 2000);
  };

  const handleCheckout = (productId) => {
    setCart(cart.map(item => {
      if (item.product.id === productId) {
        return { ...item, status: 'paid' };
      }
      return item;
    }));
    alert("Payment successful! The seller has been notified.");
  };

  if (activeItems.length === 0) {
    return <div className="text-center text-gray-500 mt-10 text-xl">Your cart is empty.</div>;
  }

  return (
    <div>
      <h2 className="text-2xl font-bold mb-6">Your Cart & Negotiations</h2>
      <div className="space-y-4">
        {activeItems.map(item => (
          <div key={item.product.id} className="bg-white p-4 rounded-lg shadow flex flex-col md:flex-row items-center justify-between gap-4">
            <div className="flex items-center gap-4 w-full md:w-1/2">
              <img src={item.product.image} alt={item.product.title} className="w-20 h-20 object-cover rounded" />
              <div>
                <h3 className="font-semibold text-lg">{item.product.title}</h3>
                <p className="text-gray-500">Asking Price: ${item.product.price}</p>
              </div>
            </div>

            <div className="w-full md:w-1/2 flex flex-col items-end gap-2">
              {item.status === 'none' || item.status === 'rejected' ? (
                <div className="flex items-center gap-2">
                  {item.status === 'rejected' && <span className="text-red-500 text-sm">Offer rejected. Try again.</span>}
                  <input 
                    type="number" 
                    defaultValue={item.product.price}
                    id={`price-${item.product.id}`}
                    className="border p-2 rounded w-24"
                  />
                  <button 
                    onClick={() => handleNegotiate(item.product.id, document.getElementById(`price-${item.product.id}`).value)}
                    className="bg-yellow-500 text-white px-4 py-2 rounded hover:bg-yellow-600"
                  >
                    Propose Price
                  </button>
                  <button 
                    onClick={() => handleCheckout(item.product.id)}
                    className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
                  >
                    Buy at ${item.product.price}
                  </button>
                </div>
              ) : item.status === 'pending' ? (
                <span className="text-yellow-600 font-semibold animate-pulse">Waiting for seller response...</span>
              ) : item.status === 'agreed' ? (
                <div className="flex items-center gap-4">
                  <span className="text-green-600 font-semibold">Offer Accepted: ${item.finalPrice}</span>
                  <button 
                    onClick={() => handleCheckout(item.product.id)}
                    className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700 font-bold"
                  >
                    Checkout Now
                  </button>
                </div>
              ) : null}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function PostItem({ products, setProducts, onBack }) {
  const [formData, setFormData] = useState({ title: '', price: '', description: '', image: '' });

