                sampleRate * duration,
                sampleRate
            );

            const source = offlineCtx.createBufferSource();
            source.buffer = originalAudioBuffer;

            let lastNode = source;

            // Apply Effects
            if (effect === 'muffled') {
                const filter = offlineCtx.createBiquadFilter();
                filter.type = 'lowpass';
                filter.frequency.value = 1000;
                lastNode.connect(filter);
                lastNode = filter;
            } else if (effect === 'telephone') {
                const filter = offlineCtx.createBiquadFilter();
                filter.type = 'bandpass';
                filter.frequency.value = 1500;
                filter.Q.value = 2.0;
                lastNode.connect(filter);
                lastNode = filter;
            } else if (effect === 'fast') {
                source.playbackRate.value = 1.5;
            }

            lastNode.connect(offlineCtx.destination);

            // Start playback at the trimmed start time
            source.start(0, start, duration);

            // Render audio
            btnApply.innerText = "Rendering...";
            btnApply.disabled = true;

            const renderedBuffer = await offlineCtx.startRendering();

            // Convert to WAV and display
            const wavBlob = bufferToWave(renderedBuffer, renderedBuffer.length);
            const wavUrl = URL.createObjectURL(wavBlob);

            editedAudioEl.src = wavUrl;
            downloadLink.href = wavUrl;
            downloadLink.download = 'edited_audio.wav';
            downloadLink.style.display = 'block';
            outputSection.style.display = 'block';

            btnApply.innerText = "Apply Edits & Render";
            btnApply.disabled = false;
        });

        // 3. Utility: Convert AudioBuffer to WAV Blob
        function bufferToWave(abuffer, len) {
            let numOfChan = abuffer.numberOfChannels,
                length = len * numOfChan * 2 + 44,
                buffer = new ArrayBuffer(length),
                view = new DataView(buffer),
                channels = [], i, sample,
                offset = 0,
                pos = 0;

            // write WAVE header
            setUint32(0x46464952);                         // "RIFF"
            setUint32(length - 8);                         // file length - 8
            setUint32(0x45564157);                         // "WAVE"
            setUint32(0x20746d66);                         // "fmt " chunk
            setUint32(16);                                 // length = 16
            setUint16(1);                                  // PCM (uncompressed)
            setUint16(numOfChan);
            setUint32(abuffer.sampleRate);
            setUint32(abuffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
            setUint16(numOfChan * 2);                      // block-align
            setUint16(16);                                 // 16-bit (hardcoded in this demo)
            setUint32(0x61746164);                         // "data" - chunk
            setUint32(length - pos - 4);                   // chunk length

            // write interleaved data
            for(i = 0; i < abuffer.numberOfChannels; i++)
                channels.push(abuffer.getChannelData(i));

            while(pos < length) {
                for(i = 0; i < numOfChan; i++) {
                    sample = Math.max(-1, Math.min(1, channels[i][offset])); // clamp
                    sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767) | 0; // scale to 16-bit signed int
                    view.setInt16(pos, sample, true);          // write 16-bit sample
                    pos += 2;
                }
                offset++                                     // next source sample
            }

            return new Blob([buffer], {type: "audio/wav"});

            function setUint16(data) {
                view.setUint16(pos, data, true);
                pos += 2;
            }

            function setUint32(data) {
                view.setUint32(pos, data, true);
                pos += 4;
            }
        }
    </script>
</body>
</html>
```

### Features Included:
1. **Recording**: Uses `navigator.mediaDevices.getUserMedia` and `MediaRecorder` to capture audio directly from the user's microphone.
2. **Trimming**: Once recorded, the audio is decoded into an `AudioBuffer`. Users can specify the start and end times in seconds to trim the audio.
3. **Sound Effects**: Uses the Web Audio API's `BiquadFilterNode` and `playbackRate` to apply simple effects (Muffled, Telephone, Chipmunk).
4. **Rendering**: Uses `OfflineAudioContext` to process the trims and effects in the background instantly without needing to play the audio out loud.
5. **Exporting**: Includes a custom WAV encoder (`bufferToWave`) to convert the processed `AudioBuffer` into a standard `.wav` file that the user can download.

