// Evaluates variables like {name} and conditional blocks like {#if isPremium} content {/if}
const renderTemplate = (template, variables) => {
  if (!template) return '';

  // 1. Process Conditional Logic: {#if variable} content {/if}
  let processed = template.replace(/{#if\s+(\w+)}([\s\S]*?){\/if}/g, (match, varName, content) => {
    // If the variable exists and is true/truthy, render the content, else remove it
    return variables[varName] ? content : '';
  });

  // 2. Process Variable Interpolation: {variable}
  processed = processed.replace(/{(\w+)}/g, (match, varName) => {
    return variables[varName] !== undefined ? variables[varName] : match;
  });

  return processed;
};

// --- Main Application Component ---

