### Key Features of this Refined Version:
1. **Zero-Dependency Architecture:** Built purely with HTML, CSS, and Vanilla JavaScript. No external libraries are required, ensuring maximum stability and zero conflict issues.
2. **State Management:** The `orderStatus` variable acts as a localized state manager. When you switch between platforms, the state resets cleanly, preventing data bleed between tabs (a common issue in unrefined market versions).
3. **Dynamic Theming:** CSS variables (`:root`) and dynamic class injection (`theme-${data.id}`) are used to instantly switch the UI to the exact brand colors of Meituan, JD, Pinduoduo, DiDi, and Ctrip.
4. **Responsive Grid Layout:** The action buttons are mapped using CSS Grid (`grid-template-columns`), ensuring perfect alignment on both desktop and mobile viewports without the overlapping issues found in older templates.

Here is a complete, executable guide to creating a chunked file upload system using Node.js for the backend and vanilla JavaScript for the frontend. 

### Step 1: Initialize the Project

Open your terminal and run the following commands to create a new directory, initialize a Node.js project, and install the required dependencies:

```bash
mkdir chunk-upload-demo
cd chunk-upload-demo
npm init -y
npm install express multer cors
```

### Step 2: Create the Backend (Node.js)

Create a file named `server.js` in the root directory. This server will handle receiving individual chunks, storing them temporarily, and then merging them into the final file inside the `file` folder.

```javascript
// server.js
const express = require('express');
const multer = require('multer');
const cors = require('cors');
const fs = require('fs');
const path = require('path');

const app = express();
const port = 3000;

app.use(cors());
app.use(express.json());
app.use(express.static('public')); // Serve frontend files

// Ensure storage directories exist
const UPLOAD_DIR = path.join(__dirname, 'file');
const TEMP_DIR = path.join(__dirname, 'file', 'temp');

if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR);
if (!fs.existsSync(TEMP_DIR)) fs.mkdirSync(TEMP_DIR);

// Configure Multer for temporary chunk storage
const upload = multer({ dest: TEMP_DIR });

// Endpoint to handle individual chunk uploads
app.post('/upload', upload.single('chunk'), (req, res) => {
    const { filename, chunkIndex } = req.body;
    const chunkPath = path.join(TEMP_DIR, `${filename}-${chunkIndex}`);

    // Rename the uploaded temp file to include the chunk index
    fs.renameSync(req.file.path, chunkPath);

    res.status(200).json({ message: `Chunk ${chunkIndex} uploaded successfully` });
});

// Endpoint to merge chunks into the final file
app.post('/merge', (req, res) => {
    const { filename, totalChunks } = req.body;
    const finalFilePath = path.join(UPLOAD_DIR, filename);

    // Create a write stream for the final file
    const writeStream = fs.createWriteStream(finalFilePath);

    let currentChunk = 0;

    const mergeNextChunk = () => {
        if (currentChunk >= totalChunks) {
            writeStream.end();
            return res.status(200).json({ message: 'File merged successfully', url: `/file/${filename}` });
        }

        const chunkPath = path.join(TEMP_DIR, `${filename}-${currentChunk}`);
        const readStream = fs.createReadStream(chunkPath);

        readStream.pipe(writeStream, { end: false });

        readStream.on('end', () => {
            fs.unlinkSync(chunkPath); // Delete the chunk after merging
            currentChunk++;
            mergeNextChunk();
        });

        readStream.on('error', (err) => {
            console.error('Error reading chunk:', err);
            res.status(500).json({ error: 'Failed to merge file' });
        });
    };

    mergeNextChunk();
});

app.listen(port, () => {
    console.log(`Server running at http://localhost:${port}`);
});
```

### Step 3: Create the Frontend

Create a folder named `public` in the root directory, and inside it, create an `index.html` file. This file will slice the selected file into chunks and send them to the backend.

```html
<!-- public/index.html -->
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chunk Upload Demo</title>
    <style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        #progress-container { width: 100%; background-color: #f3f3f3; margin-top: 20px; display: none; }
        #progress-bar { width: 0%; height: 30px; background-color: #4caf50; text-align: center; line-height: 30px; color: white; }
    </style>
</head>
<body>
    <h2>Large File Chunk Uploader</h2>
    <input type="file" id="fileInput" />
    <button onclick="uploadFile()">Upload</button>

    <div id="progress-container">
        <div id="progress-bar">0%</div>
    </div>
    <p id="status"></p>

    <script>
        const CHUNK_SIZE = 1024 * 1024; // 1MB per chunk

        async function uploadFile() {
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            if (!file) return alert('Please select a file first.');

            const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
            const filename = file.name;

            document.getElementById('progress-container').style.display = 'block';
            const progressBar = document.getElementById('progress-bar');
            const statusText = document.getElementById('status');

            statusText.innerText = 'Uploading chunks...';

            // Upload each chunk
            for (let chunkIndex = 0; chunkIndex < totalChunks; chunkIndex++) {
                const start = chunkIndex * CHUNK_SIZE;
                const end = Math.min(start + CHUNK_SIZE, file.size);
                const chunk = file.slice(start, end);

                const formData = new FormData();
                formData.append('chunk', chunk);
                formData.append('filename', filename);
                formData.append('chunkIndex', chunkIndex);

                await fetch('/upload', {
                    method: 'POST',
                    body: formData
                });

                // Update progress
                const percentComplete = Math.round(((chunkIndex + 1) / totalChunks) * 100);
                progressBar.style.width = percentComplete + '%';
                progressBar.innerText = percentComplete + '%';
            }

            // Request backend to merge chunks
            statusText.innerText = 'Merging file on server...';
            const mergeResponse = await fetch('/merge', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ filename, totalChunks })
            });

            if (mergeResponse.ok) {
                statusText.innerText = 'Upload and merge complete! File saved in the "file" folder.';
            } else {
                statusText.innerText = 'Error merging file.';
            }
        }
    </script>
</body>
</html>
```

### Step 4: Run and Test

1. Start the server by running the following command in your terminal:
   ```bash
   node server.js
   ```
2. Open your browser and navigate to `http://localhost:3000`.
3. Select a large file (e.g., a video or a large PDF) and click **Upload**.
4. You will see the progress bar update as chunks are sent. Once it reaches 100%, the server will merge the chunks.
5. Check your project directory. You will see a `file` folder containing your successfully uploaded and merged file.

